/** All translations for zizhitongjian ch.002 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "=周紀二=起昭陽赤奮若，盡上章困敦，凡四十八年。", literal: "= Zhou Annals 2 = From Zhaoyang Chifenruo through Shangzhang Kundun; forty-eight years in all.", idiomatic: "= Zhou Annals 2 = From Zhaoyang Chifenruo through Shangzhang Kundun—forty-eight years in all." },
  { zh: "1齊伐魏，取觀津。", literal: "1. Qi attacked Wei and took Guanjin.", idiomatic: "1. Qi attacked Wei and seized Guanjin." },
  { zh: "2趙侵齊，〔至〕(", literal: "2. Zhao raided Qi, [reached] (", idiomatic: "2. Zhao raided Qi, [reached] (" },
  { zh: "取)", literal: "took)", idiomatic: "took)" },
  { zh: "長城<ref>〔至〕(", literal: "the Great Wall<ref>[reached] (", idiomatic: "the Great Wall<ref>[reached] (" },
  { zh: "取)", literal: "took)", idiomatic: "took)" },
  { zh: "長城-{據}-《史記·六國年表》、《趙世家》改。", literal: "the Great Wall—emended per the \"Tables of the Six States\" and the \"House of Zhao\" in the Records of the Grand Historian.", idiomatic: "the Great Wall—emended per the \"Tables of the Six States\" and the \"House of Zhao\" in Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "3〔西周威公卒，太子朝立，是爲惠公。", literal: "3. [Duke Wei of Western Zhou died; the crown prince Chao succeeded and became Duke Hui.", idiomatic: "3. [Duke Wei of Western Zhou died; Crown Prince Chao succeeded as Duke Hui." },
  { zh: "弟公子班有寵-{於}-威公。", literal: "The younger brother, Lord Ban, was favored by Duke Wei.", idiomatic: "His younger brother, Lord Ban, had been favored by Duke Wei." },
  { zh: "威公卒，遂以反。", literal: "When Duke Wei died, he thereupon rebelled.", idiomatic: "When Duke Wei died, he rebelled." },
  { zh: "趙、韓來攻周〕<ref>西周威公卒此段-{據}-《史記·周本紀》、《趙世家》及《韓非子·内儲説下》增。", literal: "Zhao and Han came to attack Zhou]<ref>From \"Duke Wei of Western Zhou died\" this passage supplemented per the \"Basic Annals of Zhou\" and the \"House of Zhao\" in the Records of the Grand Historian and \"Inner Storage, Lower\" in Han Feizi.", idiomatic: "Zhao and Han came to attack Zhou]<ref>From \"Duke Wei of Western Zhou died\" this passage is supplemented from the \"Basic Annals of Zhou\" and \"House of Zhao\" in Records of the Grand Historian and \"Inner Storage, Lower\" in Han Feizi." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1〔趙、韓分周以爲二，王封西周惠公弟班-{於}-鞏，以奉王，是爲東周惠公。", literal: "1. [Zhao and Han divided Zhou into two; the king enfeoffed Duke Hui of Western Zhou's younger brother Ban at Gong to serve the king, and he became Duke Hui of Eastern Zhou.", idiomatic: "1. [Zhao and Han divided Zhou in two; the king enfeoffed Duke Hui of Western Zhou's younger brother Ban at Gong to serve the king—he became Duke Hui of Eastern Zhou." },
  { zh: "周-{於}-是始分爲東西。", literal: "Zhou from then on was first divided into East and West.", idiomatic: "From then on Zhou was divided into Eastern and Western courts." },
  { zh: "王室微弱，政在西周〕<ref>趙、韓分周以爲二此段-{據}-《史記·周本紀》正義引郭縁生《述-{征}-記》、《史記·趙世家》正義引《括地-{志}-》及《太平-{御}-覽》巻八十五引《帝王世紀》增。", literal: "The royal house was weak; government lay in Western Zhou]<ref>From \"Zhao and Han divided Zhou into two\" this passage supplemented per the Zhengyi to the \"Basic Annals of Zhou\" in the Records of the Grand Historian citing Guo Yuansheng's \"Account of Campaigns,\" the Zhengyi to the \"House of Zhao\" citing the \"Treatise on Lands,\" and juan 85 of the \"Imperial Digest\" citing the \"Chronicles of Emperors and Kings.\"", idiomatic: "The royal house was weak; power rested with Western Zhou]<ref>From \"Zhao and Han divided Zhou into two\" this passage is supplemented from the Zhengyi to \"Basic Annals of Zhou\" citing Guo Yuansheng's \"Account of Campaigns,\" the Zhengyi to \"House of Zhao\" citing the \"Treatise on Lands,\" and juan 85 of the \"Imperial Digest\" citing the \"Chronicles of Emperors and Kings.\"" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1魏、韓會-{于}-宅陽。", literal: "1. Wei and Han met at Zhaiyang.", idiomatic: "1. Wei and Han met at Zhaiyang." },
  { zh: "2秦敗魏師、韓師-{于}-洛〔陰〕(", literal: "2. Qin defeated the Wei and Han armies at Luo[yin] (", idiomatic: "2. Qin defeated the Wei and Han armies at Luo[yin] (" },
  { zh: "陽)", literal: "yin)", idiomatic: "yin)" },
  { zh: "<ref>秦敗魏師、韓師-{于}-洛〔陰〕(", literal: "<ref>Qin defeated the Wei and Han armies at Luo[yin] (", idiomatic: "<ref>Qin defeated the Wei and Han armies at Luo[yin] (" },
  { zh: "陽)", literal: "yin)", idiomatic: "yin)" },
  { zh: "-{據}-《史記·六國年表》改。", literal: "—emended per the \"Tables of the Six States\" in the Records of the Grand Historian.", idiomatic: "—emended per the \"Tables of the Six States\" in Records of the Grand Historian." },
  { zh: "案：「洛陰」，今陝西省大茘縣東南。", literal: "Commentary: \"Luoyin\" is southeast of present-day Dali County, Shaanxi Province.", idiomatic: "Note: \"Luoyin\" lies southeast of present-day Dali County in Shaanxi." },
  { zh: "胡三省以成周之洛陽釋之，實大誤。", literal: "Hu Sanxing interpreted it as Luoyang of Chengzhou—this is a great error.", idiomatic: "Hu Sanxing took it to mean Luoyang of Chengzhou—a serious mistake." },
  { zh: "時周之洛陽在魏、韓境内，此時秦師尚未能至此地。", literal: "At that time Zhou's Luoyang lay within Wei and Han territory; Qin troops could not yet reach this place.", idiomatic: "At that time Zhou's Luoyang lay inside Wei and Han; Qin armies could not yet reach it." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1魏伐宋，〔取儀-{臺}-〕<ref>〔取儀-{臺}-〕-{據}-《史記·六國年表》、《趙世家》補。", literal: "1. Wei attacked Song, [took Yitai]<ref>[took Yitai]—supplemented per the \"Tables of the Six States\" and the \"House of Zhao\" in the Records of the Grand Historian.", idiomatic: "1. Wei attacked Song, [taking Yitai]<ref>[taking Yitai]—supplemented from the \"Tables of the Six States\" and \"House of Zhao\" in Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1秦獻公敗三晉之師-{于}-石門，斬首六萬。", literal: "1. Duke Xian of Qin defeated the armies of the Three Jin at Shimen and beheaded sixty thousand.", idiomatic: "1. Duke Xian of Qin routed the Three Jin at Shimen and took sixty thousand heads." },
  { zh: "王賜以黼黻之服。", literal: "The king bestowed upon him robes of brocade.", idiomatic: "The Zhou king rewarded him with ceremonial robes." },
  { zh: "1〔宋休公薨，子桓公-{辟}-兵立〕<ref>〔宋休公薨，子桓公-{辟}-兵立〕舊文本-{繫}--{於}-安王三年，-{據}-近人考-{証}-移入此年，-{並}--{據}-《史記·宋世家》索隱引《紀年》改-{辟}-」爲「桓」，-{並}-補「-{辟}-兵」二字。", literal: "1. [Duke Xiu of Song died; his son Duke Huan Biping succeeded]<ref>[Duke Xiu of Song died; his son Duke Huan Biping succeeded]—old text was tied to the third year of King An; moved to this year per modern scholarship, and per Suoyin to the \"House of Song\" in the Records of the Grand Historian citing the Bamboo Annals \"Bi\" was changed to \"Huan,\" with \"Biping\" two characters supplemented.", idiomatic: "1. [Duke Xiu of Song died; his son Duke Huan Biping succeeded]<ref>[Duke Xiu of Song died; his son Duke Huan Biping succeeded]—old text placed this in the third year of King An; moved here per modern scholarship, and per Suoyin to \"House of Song\" citing the Bamboo Annals \"Bi\" was changed to \"Huan,\" with \"Biping\" added." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2〔韓懿侯薨，子昭侯武立〕<ref>〔韓懿侯薨，子昭侯武立〕舊文本-{繫}--{於}-顯王十年，-{據}-近人考-{証}-移入此年，-{並}--{據}-《史記·韓世家》索隱引《紀年》補「武」字。", literal: "2. [Marquis Yi of Han died; his son Marquis Zhao Wu succeeded]<ref>[Marquis Yi of Han died; his son Marquis Zhao Wu succeeded]—old text was tied to the tenth year of King Xian; moved to this year per modern scholarship, with the character \"Wu\" supplemented per Suoyin to the \"House of Han\" in the Records of the Grand Historian citing the Bamboo Annals.", idiomatic: "2. [Marquis Yi of Han died; his son Marquis Zhao Wu succeeded]<ref>[Marquis Yi of Han died; his son Marquis Zhao Wu succeeded]—old text placed this in the tenth year of King Xian; moved here per modern scholarship, with \"Wu\" added from Suoyin to \"House of Han\" citing the Bamboo Annals." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1魏敗韓師、趙師-{于}-澮。", literal: "1. Wei defeated the Han and Zhao armies at Hui.", idiomatic: "1. Wei defeated the Han and Zhao armies at Hui." },
  { zh: "擒樂祚。", literal: "He captured Le Zhuo.", idiomatic: "He captured Le Zhuo." },
  { zh: "〔魏王悅，郊迎，以賞田百萬祿之。", literal: "[The king of Wei was pleased, went out to the suburbs to welcome him, and rewarded him with a fief of a million and enfeoffed him with salary.", idiomatic: "[King Hui of Wei was delighted, went out to meet him in the suburbs, and granted him a fief worth a million plus an official stipend." },
  { zh: "公叔痤反走，再拜辭曰：「夫使士卒不崩，直而不倚，撓而不避者，此呉起-{餘}-教也，臣不能爲也。", literal: "Gongshu Cuo turned and withdrew, bowed twice, and declined, saying: \"That the soldiers do not break, stand straight without leaning, and bend without shirking—this is the remnant teaching of Wu Qi; your servant cannot do it.", idiomatic: "Gongshu Cuo stepped back, bowed twice, and declined: \"Keeping soldiers from breaking, standing straight without leaning, bending without flinching—that is what Wu Qi left behind; I cannot claim that." },
  { zh: "前脈形地之險阻，決利害之備，使三軍之士不迷惑者，巴-{寧}-、爨襄之力也。", literal: "To go before and trace the terrain's passes and barriers, decide preparations of advantage and harm, and keep the three armies from confusion—this is the strength of Ba Ning and Cuan Xiang.", idiomatic: "Reading the ground ahead, choosing where advantage and danger lie, keeping three armies from losing their way—that was Ba Ning and Cuan Xiang." },
  { zh: "懸賞罰-{於}-前，使民昭然信之-{於}--{後}-者，君之明法也。", literal: "To hang rewards and punishments before them and make the people clearly trust them afterward—this is your lordship's enlightened laws.", idiomatic: "Hanging rewards and punishments before the men so the people trust them afterward—that is your majesty's clear law." },
  { zh: "見敵之可撃，鼓之不敢怠倦者，臣也。", literal: "Seeing the enemy may be struck and drumming the advance without daring slackness—this is your servant.", idiomatic: "Seeing when the enemy can be hit and beating the drums without letting men slack—that was mine alone." },
  { zh: "王特爲臣之右手不倦賞臣，何也？", literal: "Your Majesty would reward your servant only for his right hand not tiring—why?", idiomatic: "Your Majesty would reward only my untiring right hand—why?" },
  { zh: "若以臣之有功，臣何力之有乎？", literal: "If it is because your servant had merit, what strength does your servant have?", idiomatic: "If you credit me with merit, what strength is truly mine?" },
  { zh: "」王曰：「善。", literal: "\" The king said: \"Well said.", idiomatic: "\" The king said: \"Well said." },
  { zh: "」-{於}-是索呉起之-{後}-，賜田二十萬。", literal: "\" Thereupon he sought out Wu Qi's descendants and granted a fief of two hundred thousand.", idiomatic: "\" He then sought out Wu Qi's descendants and granted two hundred thousand in land." },
  { zh: "巴-{寧}-、爨襄田各十萬。", literal: "Ba Ning and Cuan Xiang each received fiefs of one hundred thousand.", idiomatic: "Ba Ning and Cuan Xiang each received one hundred thousand in land." },
  { zh: "魏王曰：「公叔豈非長者哉！", literal: "The king of Wei said: \"Is Gongshu not a man of stature!", idiomatic: "King Hui said: \"Is Gongshu not a true elder!" },
  { zh: "旣爲寡人勝強敵矣，又不遺賢者之-{後}-，不掩能士之跡，公叔何可無益乎？", literal: "Having won a strong foe for me, he does not forget the descendants of the worthy, does not cover the traces of able men—how can Gongshu go unrewarded?", idiomatic: "He has beaten a strong foe for me, yet does not forget the worthy's heirs or hide able men's deeds—how can Gongshu go unrewarded?" },
  { zh: "」故又與田四十萬〕<ref>魏王悅句以下-{據}-《戰國策·魏策一》第八章補。", literal: "\" Therefore he also granted a further fief of four hundred thousand]<ref>From \"the king of Wei was pleased\" downward supplemented per chapter 8 of \"Wei Policies I\" in the Stratagems of the Warring States.", idiomatic: "\" So he granted another four hundred thousand in land]<ref>From \"the king of Wei was pleased\" onward, supplemented from chapter 8 of \"Wei Policies I\" in Stratagems of the Warring States." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2秦、魏戰-{于}-少梁，魏師敗績；", literal: "2. Qin and Wei fought at Shaoliang; the Wei army was routed;", idiomatic: "2. Qin and Wei fought at Shaoliang; the Wei army was routed;" },
  { zh: "獲魏公孫痤。", literal: "they captured the Wei heir apparent Cuo.", idiomatic: "they captured Wei heir apparent Cuo." },
  { zh: "3衞聲公薨，子成侯速立。", literal: "3. Duke Sheng of Wei died; his son Marquis Cheng Su succeeded.", idiomatic: "3. Duke Sheng of Wei died; his son Marquis Cheng Su succeeded." },
  { zh: "4燕桓公薨，子文公立。", literal: "4. Duke Huan of Yan died; his son Duke Wen succeeded.", idiomatic: "4. Duke Huan of Yan died; his son Duke Wen succeeded." },
  { zh: "5秦獻公薨，子孝公立。", literal: "5. Duke Xian of Qin died; his son Duke Xiao succeeded.", idiomatic: "5. Duke Xian of Qin died; his son Duke Xiao succeeded." },
  { zh: "孝公生二十一年矣。", literal: "Duke Xiao was twenty-one years old.", idiomatic: "Duke Xiao was twenty-one." },
  { zh: "是時河、山以東強國六，淮、泗之間小國十-{餘}-，楚、魏與秦接界。", literal: "At this time east of the Yellow River and mountains were six great powers; between the Huai and Si were more than ten small states; Chu and Wei bordered Qin.", idiomatic: "East of the Yellow River and mountains stood six great powers; between the Huai and Si lay more than ten lesser states; Chu and Wei shared borders with Qin." },
  { zh: "魏-{築}-長城，自鄭濱洛以北有上郡；", literal: "Wei built the Long Wall; from Zheng along the Luo northward it held Shang commandery;", idiomatic: "Wei had built the Long Wall; from Zheng along the Luo northward it held Shang commandery;" },
  { zh: "楚自漢中，南有巴、黔中；", literal: "Chu from Hanzhong southward held Ba and Qianzhong;", idiomatic: "Chu held Hanzhong and, southward, Ba and Qianzhong;" },
  { zh: "皆以夷翟遇秦，擯斥之，不得與中國之會盟。", literal: "all treated Qin as barbarian Di, repelled it, and would not let it join the alliances of the Central States.", idiomatic: "all treated Qin as barbarian, shut it out, and barred it from the alliances of the Central States." },
  { zh: "-{於}-是孝公-{發}-憤，布德修政，欲以強秦。", literal: "Thereupon Duke Xiao burned with resolve, spread virtue and repaired government, and wished to strengthen Qin.", idiomatic: "Then Duke Xiao burned with resolve, spread virtue and repaired government, and set out to strengthen Qin." },
  { zh: "1孝公令國中曰：「昔我穆公，自岐、雍之間修德行武，東平晉亂，以河爲界，西霸戎翟，廣地千-{里}-，天子致伯，諸侯畢賀，爲-{後}-世開業甚光美。", literal: "1. Duke Xiao issued an order within the state, saying: \"Of old our Duke Mu, from between Qi and Yong cultivated virtue and practiced arms, eastward settled Jin's disorder and took the Yellow River as boundary, westward dominated the Rong and Di, broadened territory a thousand li, received from the Son of Heaven the title of hegemon, and all feudal lords congratulated him—he opened an enterprise for posterity most bright and fine.", idiomatic: "1. Duke Xiao proclaimed throughout the state: \"Long ago Duke Mu, from Qi and Yong, cultivated virtue and took up arms; east he settled Jin's chaos and made the Yellow River his border; west he dominated the Rong and Di and widened his realm a thousand li; the Son of Heaven named him hegemon and every feudal lord came to congratulate him—he opened a glorious enterprise for generations to come." },
  { zh: "會往者厲、躁、簡公、出子之不-{寧}-，國家内憂，未遑外事。", literal: "Then came the unrest of former rulers Li, Zao, Duke Jian, and the Exiled Son; the state had inner troubles and had no leisure for outer affairs.", idiomatic: "Then came the troubled reigns of Li, Zao, Duke Jian, and the Exiled Son; the state turned inward and had no leisure for foreign affairs." },
  { zh: "三晉攻奪我先君河西地，-{醜}-莫大焉。", literal: "The Three Jin attacked and seized our former lords' lands west of the River—no disgrace could be greater.", idiomatic: "The Three Jin seized our former lords' lands west of the River—no shame could be greater." },
  { zh: "獻公卽位，鎭撫邊境，徙治櫟陽，且欲東伐，-{復}-穆公之故地，修穆公之政令。", literal: "Duke Xian upon succeeding settled and comforted the borders, moved the capital to Liyang, and wished moreover to campaign eastward, recover Duke Mu's former lands, and restore Duke Mu's government and orders.", idiomatic: "When Duke Xian came to the throne he secured the borders, moved the capital to Liyang, and meant to march east, recover Duke Mu's old lands, and restore Duke Mu's laws." },
  { zh: "寡人思念先君之意，常痛-{於}-心。", literal: "I think constantly on our former lords' intent and am ever pained at heart.", idiomatic: "I hold our former lords' purpose in mind and ache at heart." },
  { zh: "賓客群臣有能出奇計強秦者，吾且尊官，與之分土。", literal: "Among guests and ministers, whoever can offer a striking plan to strengthen Qin—I shall honor with high office and share territory with him.", idiomatic: "Any guest or minister who can offer a striking plan to strengthen Qin—I shall honor with high office and share land with him." },
  { zh: "」-{於}-是衞公孫鞅聞是令下，乃西入秦。", literal: "\" Thereupon Gongsun Yang of Wei heard this order issued and went west into Qin.", idiomatic: "\" When Gongsun Yang of Wei heard the proclamation, he went west into Qin." },
  { zh: "公孫鞅者，衞之庶孫也，好刑名之學。", literal: "Gongsun Yang was a lesser grandson of Wei and loved the learning of punishments and names.", idiomatic: "Gongsun Yang was a cadet of the house of Wei and devoted himself to the school of law and designation." },
  { zh: "事魏相公叔痤，痤知其賢，未及進。", literal: "He served Wei chancellor Gongshu Cuo; Cuo knew his worth but had not yet advanced him.", idiomatic: "He served Wei chancellor Gongshu Cuo, who knew his talent but had not yet promoted him." },
  { zh: "會病，魏惠王往問之曰：「公叔病如有不可諱，將奈社稷何？", literal: "When he fell ill, King Hui of Wei went to inquire of him, saying: \"If Chancellor Gongshu's illness reaches what may not be spoken, what is to be done for the altars of state?", idiomatic: "When he fell ill, King Hui of Wei visited him and asked: \"If your illness takes an irreversible turn, what becomes of the altars of state?" },
  { zh: "」公叔曰：「痤之中庶子衞鞅，年雖少，有奇-{才}-，-{願}-君舉國而-{聽}-之！", literal: "\" Gongshu said: \"Cuo's attendant Gongsun Yang of Wei, though young in years, has extraordinary talent—I wish Your Majesty would entrust the whole state to his hearing!", idiomatic: "\" Gongshu said: \"My attendant Gongsun Yang of Wei is young, but his talent is extraordinary—I beg Your Majesty to let him govern the whole state!" },
  { zh: "」王嘿然。", literal: "\" The king was silent.", idiomatic: "\" The king said nothing." },
  { zh: "公叔曰：「君卽不-{聽}-用鞅，必殺之，無令出境。", literal: "Gongshu said: \"If Your Majesty will not heed and employ Yang, you must kill him—do not let him leave the borders.", idiomatic: "Gongshu said: \"If you will not employ Yang, you must kill him—do not let him cross the border." },
  { zh: "」王許諾而去。", literal: "\" The king assented and left.", idiomatic: "\" The king agreed and left." },
  { zh: "公叔召鞅謝曰：「吾先君而-{後}-臣，故先爲君謀，-{後}-以告子。", literal: "Gongshu summoned Yang and apologized, saying: \"I put the ruler before the minister, therefore I first plotted for the ruler, then told you.", idiomatic: "Gongshu summoned Yang and said: \"I owe the ruler before my minister—so I advised him first, then told you." },
  { zh: "子必速行矣！", literal: "You must flee quickly!", idiomatic: "You must flee at once!" },
  { zh: "」鞅曰：「君不能用子之言任臣，又安能用子之言殺臣乎？", literal: "\" Yang said: \"If the ruler cannot employ your words to entrust me, how can he employ your words to kill me?", idiomatic: "\" Yang said: \"If the king will not heed you enough to employ me, how will he heed you enough to kill me?" },
  { zh: "」卒不去。", literal: "\" In the end he did not leave.", idiomatic: "\" He did not flee." },
  { zh: "王出，謂左右曰：「公叔病甚，悲乎！", literal: "The king left and said to those at his side: \"Chancellor Gongshu is very ill—how sad!", idiomatic: "Leaving, the king told his attendants: \"Gongshu is terribly ill—how sad!" },
  { zh: "欲令寡人以國-{聽}-衞鞅也，旣又勸寡人殺之，豈不悖哉！", literal: "He wished to have me entrust the state to Wei Yang, yet also urged me to kill him—is this not perverse!", idiomatic: "He wanted me to hand the realm to Wei Yang, then urged me to kill him—is that not absurd!" },
  { zh: "」衞鞅旣至秦，因嬖臣景監以求見孝公，説以富國強兵之-{術}-。", literal: "\" When Wei Yang had reached Qin, through the favorite minister Jing Jian he sought audience with Duke Xiao and urged the methods of enriching the state and strengthening the army.", idiomatic: "\" Once in Qin, Wei Yang won access through the favorite Jing Jian, met Duke Xiao, and argued for ways to enrich the state and strengthen the army." },
  { zh: "公大悅，與議國事。", literal: "The duke was greatly pleased and discussed state affairs with him.", idiomatic: "The duke was delighted and debated state affairs with him." },
  { zh: "2〔夏，四月，甲寅，魏自安邑徙都大梁〕<ref>夏四月句此段-{據}-《史記·魏世家》集解引《紀年》、《漢書·髙帝紀》注臣瓚引《紀年》增。", literal: "2. [In summer, the fourth month, on day jiayin, Wei moved its capital from Anyi to Daliang]<ref>From \"summer, fourth month\" this passage supplemented per the Jijie to the \"House of Wei\" in the Records of the Grand Historian citing the Bamboo Annals and the note by Chen Zan to the \"Annals of Emperor Gaozu\" in the Book of Han citing the Bamboo Annals.", idiomatic: "2. [In summer, the fourth month, on jiayin day, Wei moved its capital from Anyi to Daliang]<ref>From \"summer, fourth month\" this passage is supplemented from the Jijie to \"House of Wei\" citing the Bamboo Annals and Chen Zan's note to \"Annals of Emperor Gaozu\" citing the Bamboo Annals." },
  { zh: "《漢書·髙帝紀》注臣瓚引《紀年》以遷都大梁在魏惠王六年，今從《史記·魏世家》集解引《紀年》定-{於}-魏惠王九年，卽周顯王八年。", literal: "Chen Zan's note to the \"Annals of Emperor Gaozu\" in the Book of Han, citing the Bamboo Annals, places the move to Daliang in the sixth year of King Hui of Wei; now following the Jijie to the \"House of Wei\" in the Records of the Grand Historian citing the Bamboo Annals, it is fixed in the ninth year of King Hui of Wei, which is the eighth year of King Xian of Zhou.", idiomatic: "Chen Zan, citing the Bamboo Annals in his note to \"Annals of Emperor Gaozu,\" dates the move to Daliang to King Hui of Wei's sixth year; following the Jijie to \"House of Wei\" citing the Bamboo Annals, it is placed in his ninth year—the eighth year of King Xian of Zhou." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "3〔越大夫寺區弟思弒其君莽安，次無顓立〕。", literal: "3. [The Yue grandee Siqu's younger brother Si assassinated his lord Mang'an; next Wuzhuan succeeded.]", idiomatic: "3. [The Yue grandee Siqu's younger brother Si assassinated Lord Mang'an; Wuzhuan succeeded next.]" },
  { zh: "〔越人三世弒其君，王子搜患之，逃乎丹穴。", literal: "[The people of Yue thrice assassinated their lords; Prince Sou was troubled by it and fled to Danyue.", idiomatic: "[The Yue had murdered three lords in succession; Prince Sou, sickened by it, fled to Danyue." },
  { zh: "而越國無君，求王子搜不得，從之丹穴。", literal: "Yue was without a lord; they sought Prince Sou but could not find him and followed him to Danyue.", idiomatic: "Yue was left without a ruler; they could not find Prince Sou and tracked him to Danyue." },
  { zh: "王子搜不肯出，越人薰之以艾。", literal: "Prince Sou would not come out; the people of Yue smoked him out with mugwort.", idiomatic: "Prince Sou refused to emerge; the Yue smoked him out with mugwort." },
  { zh: "乘以王輿。", literal: "They placed him in the royal carriage.", idiomatic: "They lifted him into the royal carriage." },
  { zh: "王子搜援緩登車，仰天而呼曰：「君乎！", literal: "Prince Sou, holding the rope, slowly mounted the carriage, looked up to Heaven and cried: \"My lord!", idiomatic: "Prince Sou took the rope and climbed slowly into the carriage, looked up to Heaven and cried: \"My lord!" },
  { zh: "君乎！", literal: "My lord!", idiomatic: "My lord!" },
  { zh: "獨不可以-{舍}-我乎！", literal: "Can you alone not spare me!", idiomatic: "Could you not spare me alone!" },
  { zh: "」王子搜號曰無顓〕<ref>越大夫寺區弟思弒其君莽安句此段-{據}-《史記·越世家》索隱引《紀年》、《莊子·讓王篇》、《呂氏春秋·貴生篇》增，依楊寬《戰國史料編年輯-{証}-》越君年世之考訂-{繫}--{於}-此年。", literal: "\" Prince Sou took the style name Wuzhuan]<ref>From \"the Yue grandee Siqu's younger brother Si assassinated his lord Mang'an\" this passage supplemented per Suoyin to the \"House of Yue\" in the Records of the Grand Historian citing the Bamboo Annals, \"The Kings Who Yielded the Throne\" in Zhuangzi, and \"Cherishing Life\" in Master Lü's Spring and Autumn Annals, tied to this year per Yang Kuan's chronological compilation and verification of Yue rulers' reigns.", idiomatic: "\" Prince Sou took the name Wuzhuan]<ref>From \"the Yue grandee Siqu's younger brother Si assassinated Lord Mang'an\" this passage is supplemented from Suoyin to \"House of Yue\" citing the Bamboo Annals, Zhuangzi \"Kings Who Yielded the Throne,\" and Lüshi Chunqiu \"Cherishing Life,\" dated to this year per Yang Kuan's chronology of Yue rulers." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1衞鞅欲變法，秦人不悅。", literal: "1. Wei Yang wished to change the laws; the people of Qin were displeased.", idiomatic: "1. Wei Yang wished to reform the laws; the people of Qin were displeased." },
  { zh: "衞鞅言-{於}-秦孝公曰：「夫民不可與慮始，而可與樂成。", literal: "Wei Yang spoke to Duke Xiao of Qin, saying: \"The people cannot be consulted about beginnings, but they may share in rejoicing at completion.", idiomatic: "Wei Yang told Duke Xiao of Qin: \"The people cannot be consulted at the start, but they may rejoice when the work is done." },
  { zh: "論至德者不和-{於}-俗，成大功者不謀-{於}-衆。", literal: "One who discourses on utmost virtue does not harmonize with custom; one who completes great achievement does not plot with the multitude.", idiomatic: "Those who speak of highest virtue do not trim their words to fashion; those who finish great deeds do not take counsel from the crowd." },
  { zh: "是以聖人苟可以強國，不法其故。", literal: "Thus the sage, if he can strengthen the state, does not take its old ways as his law.", idiomatic: "Thus the sage, if he can strengthen the state, does not take its old ways as his law." },
  { zh: "」甘龍曰：「不然。", literal: "\" Gan Long said: \"Not so.", idiomatic: "\" Gan Long said: \"Not so." },
  { zh: "縁法而治者，吏習而民安之。", literal: "Those who govern by following the law—the clerks are practiced at it and the people rest secure.", idiomatic: "Those who govern by following the law—the clerks are practiced at it and the people rest secure." },
  { zh: "」衞鞅曰：「常人安-{於}-故俗，學者溺-{於}-所聞，以此兩者，居官守法可也，非所與論-{於}-法之外也。", literal: "\" Wei Yang said: \"Ordinary men rest content in old custom; scholars drown in what they have heard. With these two sorts, one may hold office and keep the law—but they are not fit to debate what lies outside the law.\"", idiomatic: "\" Wei Yang said: \"Ordinary men rest content in old custom; scholars drown in what they have heard. With these two sorts, one may hold office and keep the law—but they are not fit to debate what lies outside the law.\"" },
  { zh: "智者作法，愚者-{制}-焉；", literal: "The wise make the law; fools are constrained by it;", idiomatic: "The wise make the law; fools are constrained by it;" },
  { zh: "賢者更禮，不肖者拘焉。", literal: "the worthy change ritual; the unworthy are bound by it.", idiomatic: "the worthy change ritual; the unworthy are bound by it." },
  { zh: "」公曰：「善。", literal: "\" The duke said: \"Good.", idiomatic: "\" The duke said: \"Good." },
  { zh: "」以衞鞅爲左庶長，卒定變法之令。", literal: "\" He made Wei Yang Left Chief Minister and in the end fixed the orders of reform.", idiomatic: "\" He made Wei Yang Left Chief Minister and in the end fixed the orders of reform." },
  { zh: "令民爲什伍而相〔牧〕(", literal: "He ordered the people organized in groups of ten and five to mutually [oversee] (", idiomatic: "He ordered the people organized in groups of ten and five to mutually [oversee] (" },
  { zh: "收)", literal: "collect and control)", idiomatic: "collect and control)" },
  { zh: "司、連坐<ref>〔牧〕(", literal: "control, and joint liability<ref>[oversee] (", idiomatic: "control, and joint liability<ref>[oversee] (" },
  { zh: "收)", literal: "collect and control)", idiomatic: "collect and control)" },
  { zh: "司-{據}-《史記·商君列傳》改。", literal: "control emended per the \"Biography of Lord Shang\" in the Records of the Grand Historian.", idiomatic: "control emended per the \"Biography of Lord Shang\" in the Records of the Grand Historian." },
  { zh: "</ref>，告-{奸}-者與斬敵首同賞，〔匿〕(", literal: "</ref>; those who report {traitors} receive the same reward as for beheading an enemy, [those who conceal] (", idiomatic: "</ref>; those who report traitors receive the same reward as for beheading an enemy, [those who conceal] (" },
  { zh: "不告)", literal: "do not report)", idiomatic: "do not report)" },
  { zh: "-{奸}-者與降敵同罰<ref>〔匿〕(", literal: "traitors receive the same punishment as surrendering to the enemy<ref>[conceal] (", idiomatic: "traitors receive the same punishment as surrendering to the enemy<ref>[conceal] (" },
  { zh: "不告)", literal: "do not report)", idiomatic: "do not report)" },
  { zh: "-{奸}-者-{據}-《史記·商君列傳》改。", literal: "traitors emended per the \"Biography of Lord Shang\" in the Records of the Grand Historian.", idiomatic: "traitors emended per the \"Biography of Lord Shang\" in the Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "〔民有二男以上不分異者，倍其賦〕<ref>〔民有二男以上不分異者，倍其賦〕-{據}-《史記·商君列傳》補。", literal: "[Households with two or more adult sons that did not divide into separate registers had their levies doubled]<ref>[Households with two or more adult sons that did not divide into separate registers had their levies doubled] supplemented per the \"Biography of Lord Shang\" in the Records of the Grand Historian.", idiomatic: "[Households with two or more adult sons that did not divide into separate registers had their levies doubled]. Note: supplemented from the \"Biography of Lord Shang\" in the Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "有軍功者，各以率受上爵。", literal: "Those with military merit each received lofty ranks according to their measure.", idiomatic: "Those with military merit each received lofty ranks according to their measure." },
  { zh: "爲私-{鬥}-者，各以輕重被刑大小。", literal: "For private brawling, each suffered punishments great or small according to severity.", idiomatic: "For private brawling, each suffered punishments great or small according to severity." },
  { zh: "僇力本業，耕織致粟帛多者，-{復}-其身。", literal: "They honored strength in the fundamental occupation; those who in farming and weaving produced much grain and silk had their levies remitted.", idiomatic: "They honored strength in the fundamental occupation; those who in farming and weaving produced much grain and silk had their levies remitted." },
  { zh: "事末利及怠而貧者，舉以爲收孥。", literal: "Those who engaged in secondary profit and were idle and poor were wholly taken as state bondsmen.", idiomatic: "Those who engaged in secondary profit and were idle and poor were wholly taken as state bondsmen." },
  { zh: "宗室非有軍功論，不得爲屬籍。", literal: "Clans of the ruling house, unless ranked by military merit, could not remain on the lineage registers.", idiomatic: "Clans of the ruling house, unless ranked by military merit, could not remain on the lineage registers." },
  { zh: "明尊卑爵秩等級，各以差次，名田宅、臣妾、衣服〔以家次〕<ref>〔以家次〕-{據}-《史記·商君列傳》改。", literal: "They clarified the grades of noble and base, ranks and degrees, each according to its order, fixing fields, houses, servants and concubines, and clothing [by household rank]<ref>[by household rank] emended per the \"Biography of Lord Shang\" in the Records of the Grand Historian.", idiomatic: "They clarified the grades of noble and base, ranks and degrees, each according to its order, fixing fields, houses, servants and concubines, and clothing [by household rank]. Note: [by household rank] emended per the \"Biography of Lord Shang\" in the Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "有功者顯榮，無功者雖富無所芬華。", literal: "Those with merit had visible glory; those without merit, though rich, had no splendor to display.", idiomatic: "Those with merit had visible glory; those without merit, though rich, had no splendor to display." },
  { zh: "令旣具，未布，恐民之不信，乃立三丈之木-{於}-國都市南門，募民有能徙置北門者予十金。", literal: "When the orders were complete but not yet promulgated, fearing the people would not believe, he set up a pole thirty feet high at the south gate of the capital market and offered ten gold to any who could move it to the north gate.", idiomatic: "When the orders were complete but not yet promulgated, fearing the people would not believe, he set up a pole thirty feet high at the south gate of the capital market and offered ten gold to any who could move it to the north gate." },
  { zh: "民怪之，莫敢徙。", literal: "The people thought it strange; none dared move it.", idiomatic: "The people thought it strange; none dared move it." },
  { zh: "-{復}-曰：「能徙者予五十金！", literal: "He again said: \"Whoever can move it shall receive fifty gold!", idiomatic: "He again said: \"Whoever can move it shall receive fifty gold!" },
  { zh: "」有一人徙之，輒予五十金，〔以明不欺〕<ref>〔以明不欺〕-{據}-《史記·商君列傳》補。", literal: "\" One man moved it; he at once gave him fifty gold, [to show he would not deceive]<ref>[to show he would not deceive] supplemented per the \"Biography of Lord Shang\" in the Records of the Grand Historian.", idiomatic: "\" One man moved it; he at once gave him fifty gold, [to show he would not deceive]. Note: [to show he would not deceive] supplemented from the \"Biography of Lord Shang\" in the Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "乃下令。", literal: "Thereupon he issued the orders.", idiomatic: "Thereupon he issued the orders." },
  { zh: "令行期年，秦民之國都言新令之不便者以千數。", literal: "When the orders had been in force a full year, Qin people at the capital who said the new orders were inconvenient numbered in the thousands.", idiomatic: "When the orders had been in force a full year, Qin people at the capital who said the new orders were inconvenient numbered in the thousands." },
  { zh: "-{於}-是太子犯法。", literal: "Thereupon the crown prince violated the law.", idiomatic: "Thereupon the crown prince violated the law." },
  { zh: "衞鞅曰：「法之不行，自上犯之。", literal: "Wei Yang said: \"When the law does not prevail, it is because those above violate it.", idiomatic: "Wei Yang said: \"When the law does not prevail, it is because those above violate it." },
  { zh: "」〔將法太子〕<ref>〔將法太子〕-{據}-《史記·商君列傳》補。", literal: "\" [He was about to punish the crown prince]<ref>[He was about to punish the crown prince] supplemented per the \"Biography of Lord Shang\" in the Records of the Grand Historian.", idiomatic: "\" [He was about to punish the crown prince]. Note: [He was about to punish the crown prince] supplemented from the \"Biography of Lord Shang\" in the Records of the Grand Historian." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "太子，君嗣也，不可施刑。", literal: "The crown prince is the lord's heir; punishment cannot be applied to him.", idiomatic: "The crown prince is the lord's heir; punishment cannot be applied to him." },
  { zh: "刑其傅公子虔，黥其師公孫賈。", literal: "They punished his tutor Prince Qian and branded his teacher Gongsun Jia.", idiomatic: "They punished his tutor Prince Qian and branded his teacher Gongsun Jia." },
  { zh: "明日，秦人皆趨令。", literal: "The next day, all Qin people hurried to obey the orders.", idiomatic: "The next day, all Qin people hurried to obey the orders." },
  { zh: "行之十年，秦國道不拾遺，山無盜賊，民勇-{於}-公戰，怯-{於}-私-{鬥}-，鄕邑大治。", literal: "After ten years of enforcement, in Qin no one picked up lost things on the road and there were no bandits in the hills; the people were bold in public war and timid in private brawling; villages and districts were greatly well governed.", idiomatic: "After ten years of enforcement, in Qin no one picked up lost things on the road and there were no bandits in the hills; the people were bold in public war and timid in private brawling; villages and districts were greatly well governed." },
  { zh: "秦民初言令不便者，有來言令便。", literal: "Among Qin people who at first said the orders were inconvenient, some came to say the orders were convenient.", idiomatic: "Among Qin people who at first said the orders were inconvenient, some came to say the orders were convenient." },
  { zh: "衞鞅曰：「此皆亂法之民也！", literal: "Wei Yang said: \"These are all people who disturb the law!", idiomatic: "Wei Yang said: \"These are all people who disturb the law!" },
  { zh: "」盡遷之-{於}-邊。", literal: "\" He had them all relocated to the frontier.", idiomatic: "\" He had them all relocated to the frontier." },
  { zh: "其-{後}-民莫敢議令。", literal: "After that, none among the people dared discuss the orders.", idiomatic: "After that, none among the people dared discuss the orders." },
  { zh: "::臣光曰：夫信者，人君之大寶也。", literal: ":: Your servant Guang says: Faithfulness is the great treasure of a ruler.", idiomatic: "Sima Guang remarks: Faithfulness is the great treasure of a ruler." },
  { zh: "國保-{於}-民，民保-{於}-信。", literal: "The state is secured by the people; the people are secured by faithfulness.", idiomatic: "The state is secured by the people; the people are secured by faithfulness." },
  { zh: "非信無以使民，非民無以守國。", literal: "Without faithfulness one cannot employ the people; without the people one cannot guard the state.", idiomatic: "Without faithfulness one cannot employ the people; without the people one cannot guard the state." },
  { zh: "是故古之王者不欺四海，霸者不欺四鄰，善爲國者不欺其民，善爲家者不欺其親。", literal: "Therefore the ancient kings did not deceive the four seas; hegemons did not deceive the four neighbors; those skilled at governing a state did not deceive their people; those skilled at managing a family did not deceive their kin.", idiomatic: "Therefore the ancient kings did not deceive the four seas; hegemons did not deceive the four neighbors; those skilled at governing a state did not deceive their people; those skilled at managing a family did not deceive their kin." },
  { zh: "不善者反之：欺其鄰國，欺其百姓，甚者欺其兄弟，欺其父子。", literal: "The unskilled did the opposite: they deceived neighboring states, deceived their commoners, and in extreme cases deceived their brothers and deceived their fathers and sons.", idiomatic: "The unskilled did the opposite: they deceived neighboring states, deceived their commoners, and in extreme cases deceived their brothers and deceived their fathers and sons." },
  { zh: "上不信下，下不信上，上下離心，以至-{於}-敗。", literal: "When superiors do not trust inferiors and inferiors do not trust superiors, high and low lose heart and ruin follows.", idiomatic: "When superiors do not trust inferiors and inferiors do not trust superiors, high and low lose heart and ruin follows." },
  { zh: "所利不能藥其所傷，所獲不能補其所亡，豈不哀哉！", literal: "What they gained could not cure what they harmed; what they seized could not make up what they lost—is it not pitiable!", idiomatic: "What they gained could not cure what they harmed; what they seized could not make up what they lost—is it not pitiable!" },
  { zh: "昔齊桓公不背曹沫之盟，晉文公不貪伐原之利，魏文侯不棄虞人之期，秦孝公不廢徙木之賞。", literal: "Of old Duke Huan of Qi did not break the covenant at sword-point with Cao Mo; Duke Wen of Jin did not covet the profit of attacking Yuan; Marquis Wen of Wei did not abandon the forest guard's appointment; Duke Xiao of Qin did not revoke the reward for moving the pole.", idiomatic: "Of old Duke Huan of Qi did not break the covenant at sword-point with Cao Mo; Duke Wen of Jin did not covet the profit of attacking Yuan; Marquis Wen of Wei did not abandon the forest guard's appointment; Duke Xiao of Qin did not revoke the reward for moving the pole." },
  { zh: "此四君者，道非粹白，而商君尤稱刻薄，又處戰攻之世，天下趨-{於}-詐力，猶且不敢忘信以畜其民，況爲四海治平之政者哉！", literal: "These four lords—their Way was not pure white, and Lord Shang is especially called harsh and mean; moreover they lived in an age of war and attack, when all under heaven rushed toward deceit and force—yet they still did not dare forget faithfulness in nurturing their people: how much more those who govern a realm of universal peace!", idiomatic: "These four lords—their Way was not pure white, and Lord Shang is especially called harsh and mean; moreover they lived in an age of war and attack, when all under heaven rushed toward deceit and force—yet they still did not dare forget faithfulness in nurturing their people: how much more those who govern a realm of universal peace!" },
  { zh: "1秦敗韓師-{于}-西山。", literal: "1 Qin defeated Han's army at Western Mountain.", idiomatic: "1. Qin defeated Han's army at Western Mountain." },
  { zh: "1魏、〔趙〕(", literal: "1 Wei and [Zhao] (", idiomatic: "1. Wei and [Zhao] (" },
  { zh: "韓)", literal: "Han)", idiomatic: "Han)" },
  { zh: "會-{于}-鄗<ref>魏〔趙〕(", literal: "met at Hao<ref>Wei [Zhao] (", idiomatic: "met at Hao<ref>Wei [Zhao] (" },
  { zh: "韓)", literal: "Han)", idiomatic: "Han)" },
  { zh: "會-{于}-鄗章校「十二行本『韓』作『趙』；", literal: "met at Hao collation note: \"In the twelve-line edition 'Han' reads 'Zhao';", idiomatic: "met at Hao collation note: \"In the twelve-line edition 'Han' reads 'Zhao';" },
  { zh: "乙十一行本同；", literal: "the eleven-line edition B agrees;", idiomatic: "the eleven-line edition B agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "張校同。", literal: "Zhang's collation agrees.", idiomatic: "Zhang's collation agrees." },
  { zh: "」，《史記·魏世家》、《六國年表》同，-{據}-改。", literal: "\" The \"House of Wei\" in the Records of the Grand Historian and the \"Tables of the Six States\" agree; emended accordingly.", idiomatic: "\" The \"House of Wei\" in the Records of the Grand Historian and the \"Tables of the Six States\" agree; emended accordingly." },
  { zh: "楊寬注：「鄗爲趙之城邑，不得爲魏、韓君相會之地。", literal: "Yang Kuan's note: \"Hao is a city of Zhao and cannot be a place where the lords of Wei and Han met.", idiomatic: "Yang Kuan's note: \"Hao is a city of Zhao and cannot be a place where the lords of Wei and Han met." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2〔齊桓公薨，子威王因齊立〕<ref>〔齊桓公薨，子威王因齊立〕舊文本-{繫}--{於}-安王二十三年，-{據}-近人考-{証}-移入此年，-{並}-刪「是歳」、「亦」三字。", literal: "2 [Duke Huan of Qi died; his son King Wei succeeded in Qi]<ref>[Duke Huan of Qi died; his son King Wei succeeded in Qi] the old text placed this under King An year twenty-three; moved to this year per modern scholarly dating, and deleted the three characters \"this year\" and \"also.\"", idiomatic: "2. [Duke Huan of Qi died; his son King Wei succeeded in Qi]. Note: the old text placed this under King An year twenty-three; moved to this year per modern scholarly dating, and deleted the three characters \"this year\" and \"also.\"" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1〔齊威王召卽墨大夫，語之曰：「自子之居卽墨也，毀言日至。", literal: "1 [King Wei of Qi summoned the grandee of Jimo and said to him: \"Since you have dwelt in Jimo, words of slander have come day by day.", idiomatic: "1. [King Wei of Qi summoned the grandee of Jimo and said to him: \"Since you have dwelt in Jimo, words of slander have come day by day." },
  { zh: "然吾使人視卽墨，田野-{辟}-，人民給，官無事，東方以-{寧}-。", literal: "Yet I sent men to view Jimo: the fields were opened, the people supplied, the offices without trouble, and the east was thereby at peace.", idiomatic: "Yet I sent men to view Jimo: the fields were opened, the people supplied, the offices without trouble, and the east was thereby at peace." },
  { zh: "是子不事吾左右以求助也。", literal: "This shows you did not serve my attendants to seek favor.", idiomatic: "This shows you did not serve my attendants to seek favor." },
  { zh: "」封之萬家。", literal: "\" He enfeoffed him with ten thousand households.", idiomatic: "\" He enfeoffed him with ten thousand households." },
  { zh: "召阿大夫，語之曰：「自子守阿，譽言日至。", literal: "He summoned the grandee of A and said to him: \"Since you have guarded A, words of praise have come day by day.", idiomatic: "He summoned the grandee of A and said to him: \"Since you have guarded A, words of praise have come day by day." },
  { zh: "吾使人視阿，田野不-{辟}-，人民貧餒。", literal: "I sent men to view A: the fields were not opened, the people poor and hungry.", idiomatic: "I sent men to view A: the fields were not opened, the people poor and hungry." },
  { zh: "昔日趙攻鄄，子不救；", literal: "Once when Zhao attacked Juan, you did not rescue it;", idiomatic: "Once when Zhao attacked Juan, you did not rescue it;" },
  { zh: "衞取薛陵，子不知。", literal: "when Wei took Xueling, you did not know.", idiomatic: "when Wei took Xueling, you did not know." },
  { zh: "是子厚幣事吾左右以求譽也。", literal: "This shows you heaped gifts on my attendants to seek praise.", idiomatic: "This shows you heaped gifts on my attendants to seek praise." },
  { zh: "」是日，烹阿大夫及左右嘗譽者。", literal: "\" That day he boiled the grandee of A and the attendants who had praised him.", idiomatic: "\" That day he boiled the grandee of A and the attendants who had praised him." },
  { zh: "-{於}-是群臣聳懼，莫敢飾詐，務盡其情，齊國大治，強-{於}-天下〕<ref>〔齊威王召卽墨大夫〕句舊文本-{繫}--{於}-烈王六年，-{據}-近人考-{証}-移入此年。", literal: "Thereupon the ministers were startled and afraid; none dared adorn deceit and all strove to lay bare the truth; Qi was greatly well governed and strong under heaven]<ref>The passage beginning [King Wei of Qi summoned the grandee of Jimo] was placed in the old text under King Lie year six; moved to this year per modern scholarly dating.", idiomatic: "Thereupon the ministers were startled and afraid; none dared adorn deceit and all strove to lay bare the truth; Qi was greatly well governed and strong under heaven]. Note: the passage beginning [King Wei of Qi summoned the grandee of Jimo] was placed in the old text under King Lie year six; moved to this year per modern scholarly dating." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2趙、燕會-{于}-阿。", literal: "2 Zhao and Yan met at A.", idiomatic: "2. Zhao and Yan met at A." },
  { zh: "3趙、齊、宋會-{于}-平陸。", literal: "3 Zhao, Qi, and Song met at Pinglu.", idiomatic: "3. Zhao, Qi, and Song met at Pinglu." },
  { zh: "4〔魯、衞、宋、韓君朝魏〕<ref>〔魯衞宋韓君朝魏〕-{據}-《史記·魏世家》補，以應下年文「泗上十二諸侯皆來朝」。", literal: "4 [The lords of Lu, Wei, Song, and Han paid court to Wei]<ref>[The lords of Lu, Wei, Song, and Han paid court to Wei] supplemented per the \"House of Wei\" in the Records of the Grand Historian, to match next year's text \"the twelve feudal lords on the Si all came to court.\"", idiomatic: "4. [The lords of Lu, Wei, Song, and Han paid court to Wei]. Note: supplemented from the \"House of Wei\" in the Records of the Grand Historian, to match next year's text \"the twelve feudal lords on the Si all came to court.\"" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1齊威王、魏惠王會田-{于}-郊。", literal: "1 King Wei of Qi and King Hui of Wei met in the fields at the suburbs.", idiomatic: "1. King Wei of Qi and King Hui of Wei met in the fields at the suburbs." },
  { zh: "惠王曰：「齊亦有寶乎？", literal: "King Hui said: \"Does Qi also have treasures?", idiomatic: "King Hui said: \"Does Qi also have treasures?" },
  { zh: "」威王曰：「無有。", literal: "\" King Wei said: \"None.", idiomatic: "\" King Wei said: \"None." },
  { zh: "」惠王曰：「寡人國雖小，尚有徑寸之珠，照車前-{後}-各十二乘者十枚。", literal: "\" King Hui said: \"Though my state is small, I still have pearls an inch across that light up twelve chariots before and behind—ten of them.", idiomatic: "\" King Hui said: \"Though my state is small, I still have pearls an inch across that light up twelve chariots before and behind—ten of them." },
  { zh: "豈以齊大國而無寶乎？", literal: "Can it be that a great state like Qi has no treasures?", idiomatic: "Can it be that a great state like Qi has no treasures?" },
  { zh: "」威王曰：「寡人之所以爲寶者與王異。", literal: "\" King Wei said: \"What I take as treasure differs from Your Majesty.", idiomatic: "\" King Wei said: \"What I take as treasure differs from Your Majesty." },
  { zh: "吾臣有檀子者，使守南城，則楚人不敢爲寇，泗上十二諸侯皆來朝；", literal: "I have a minister Tanzi: when I set him to guard the southern city, Chu men dared not raid, and the twelve feudal lords on the Si all came to court;", idiomatic: "I have a minister Tanzi: when I set him to guard the southern city, Chu men dared not raid, and the twelve feudal lords on the Si all came to court;" },
  { zh: "吾臣有盻子者，使守髙唐，則趙人不敢東漁-{于}-河；", literal: "I have a minister Xianzi: when I set him to guard Gaotang, Zhao men dared not fish eastward on the river;", idiomatic: "I have a minister Xianzi: when I set him to guard Gaotang, Zhao men dared not fish eastward on the river;" },
  { zh: "吾吏有黔夫者，使守徐州，則燕人祭北門，趙人祭西門，徙而從者七千-{餘}-家；", literal: "I have an officer Qianfu: when I set him to guard Xuzhou, Yan men made offerings at the north gate and Zhao men at the west gate, and those who moved to follow him numbered more than seven thousand households;", idiomatic: "I have an officer Qianfu: when I set him to guard Xuzhou, Yan men made offerings at the north gate and Zhao men at the west gate, and those who moved to follow him numbered more than seven thousand households;" },
  { zh: "吾臣有-{種}-首者，使備盜賊，則道不拾遺。", literal: "I have a minister Zhongshou: when I set him to guard against bandits, none picked up lost things on the road.", idiomatic: "I have a minister Zhongshou: when I set him to guard against bandits, none picked up lost things on the road." },
  { zh: "此四臣者，將照千-{里}-，豈特十二乘哉！", literal: "These four ministers will light a thousand li—how could it be only twelve chariots!", idiomatic: "These four ministers will light a thousand li—how could it be only twelve chariots!" },
  { zh: "」惠王有慚色。", literal: "\" King Hui showed a look of shame.", idiomatic: "\" King Hui showed a look of shame." },
  { zh: "2秦孝公、魏惠王會-{于}-杜平。", literal: "2 Duke Xiao of Qin and King Hui of Wei met at Duping.", idiomatic: "2. Duke Xiao of Qin and King Hui of Wei met at Duping." },
  { zh: "1秦敗魏師-{于}-元-{里}-，斬首七千級，取少梁。", literal: "1 Qin defeated the Wei army at Yuanli, severed seventy thousand heads, and took Shaoliang.", idiomatic: "1 Qin defeated the Wei army at Yuanli, took seventy thousand heads, and seized Shaoliang." },
  { zh: "2魏惠王伐趙，圍邯鄲。", literal: "2 King Hui of Wei attacked Zhao and besieged Handan.", idiomatic: "2 King Hui of Wei attacked Zhao and besieged Handan." },
  { zh: "楚王使景-{舍}-救趙。", literal: "The king of Chu sent Jing She to rescue Zhao.", idiomatic: "The king of Chu sent Jing She to rescue Zhao." },
  { zh: "1齊威王使田忌救趙。", literal: "1 King Wei of Qi sent Tian Ji to rescue Zhao.", idiomatic: "1 King Wei of Qi sent Tian Ji to rescue Zhao." },
  { zh: "初，孫臏與龐涓倶學兵法。", literal: "At first Sun Bin and Pang Juan studied military strategy together.", idiomatic: "At first Sun Bin and Pang Juan studied the art of war together." },
  { zh: "龐涓仕魏爲將軍，自以能不及孫臏，乃召之。", literal: "Pang Juan served Wei as general; thinking himself no match for Sun Bin, he summoned him.", idiomatic: "Pang Juan entered Wei’s service as a general. Knowing himself inferior to Sun Bin, he summoned him." },
  { zh: "至，則以法斷其兩足而黥之，欲使終身廢棄。", literal: "When Sun Bin arrived, by law they cut off both his feet and branded him, intending that he be ruined for life.", idiomatic: "When he arrived, they cut off both his feet by law and branded him, meaning to ruin him for life." },
  { zh: "齊使者至魏，孫臏以刑徒陰見，説齊使者。", literal: "When a Qi envoy came to Wei, Sun Bin, as a convict, met him in secret and persuaded the Qi envoy.", idiomatic: "When a Qi envoy came to Wei, Sun Bin met him in secret as a convict and won him over." },
  { zh: "齊使者竊載與之齊。", literal: "The Qi envoy secretly carried him off to Qi.", idiomatic: "The Qi envoy stole him away to Qi." },
  { zh: "田忌善而客待之，進-{於}-威王。", literal: "Tian Ji treated him well and kept him as a guest, then presented him to King Wei.", idiomatic: "Tian Ji favored him and received him as a guest, then introduced him to King Wei." },
  { zh: "威王問兵法，遂以爲師。", literal: "King Wei questioned him on strategy and thereupon made him his teacher.", idiomatic: "King Wei questioned him on strategy and made him his teacher." },
  { zh: "-{於}-是威王謀救趙，以孫臏爲將，辭以刑-{餘}-之人不可。", literal: "Then King Wei planned to rescue Zhao and would have made Sun Bin general, but Sun Bin declined on the ground that a man mutilated by punishment was unfit.", idiomatic: "When King Wei planned to rescue Zhao and would have made Sun Bin general, Sun Bin declined: a man broken by punishment could not command." },
  { zh: "乃以田忌爲將而孫子爲師，居輜車中，坐爲計謀。", literal: "So Tian Ji was made general and Master Sun strategist; he rode in the supply wagon and sat planning.", idiomatic: "So Tian Ji was made general and Master Sun strategist; he rode in the supply train and sat plotting." },
  { zh: "田忌欲引兵之趙。", literal: "Tian Ji wished to lead the army to Zhao.", idiomatic: "Tian Ji wanted to march the army to Zhao." },
  { zh: "孫子曰：「夫解雜亂紛糾者不控拳，救-{斗}-者不搏撠。", literal: "Master Sun said, “One who unties tangled disorder does not clench his fists; one who stops a brawl does not grapple.", idiomatic: "Master Sun said, “To untangle a knot you do not clench your fists; to break up a fight you do not wrestle." },
  { zh: "批亢搗虚，形格勢禁，則自爲解耳。", literal: "Strike the throat, hit the void—when form checks momentum, it resolves of itself.", idiomatic: "Strike the vital point, hit the empty place—when form blocks force, the knot loosens by itself." },
  { zh: "今梁、趙相攻，輕兵鋭卒必竭-{於}-外，老弱疲-{於}-内。", literal: "Now Liang and Zhao fight each other; light troops and sharp soldiers must be spent without, the old and weak worn within.", idiomatic: "Now Liang and Zhao are at war; their best troops must be spent abroad and the old and weak worn out at home." },
  { zh: "子不若引兵疾走魏都，-{據}-其街路，-{衝}-其方虚，彼必釋趙以自救。", literal: "You had better march swiftly on the Wei capital, hold its thoroughfares, and strike where they are empty—they will surely abandon Zhao to save themselves.", idiomatic: "Better march hard on the Wei capital, seize its roads, and strike where they are hollow—they will surely drop Zhao to save themselves." },
  { zh: "是我一舉解趙之圍而收弊-{於}-魏也。", literal: "Thus in one move we lift the siege of Zhao and harvest Wei’s exhaustion.", idiomatic: "Thus in one stroke we lift Zhao’s siege and harvest Wei’s exhaustion." },
  { zh: "」田忌從之。", literal: "” Tian Ji followed this counsel.", idiomatic: "” Tian Ji did as he said." },
  { zh: "〔冬〕，十月<ref>〔冬〕十月-{據}-《通-{鑑}-》通例補。", literal: "[Winter], the tenth month<ref>[Winter], tenth month—supplied per the Tongjian’s usual practice;", idiomatic: "[Winter], the tenth month<ref>[Winter], tenth month—supplied per the Tongjian’s usual practice;" },
  { zh: "</ref>，邯鄲降魏。", literal: "</ref>, Handan surrendered to Wei.", idiomatic: "</ref>, Handan surrendered to Wei." },
  { zh: "魏師還，〔棄其輜重，兼趣-{舍}-而至〕<ref>〔棄其輜重，兼趣-{舍}-而至〕-{據}-《孫臏兵法·擒龐涓》補。", literal: "The Wei army returned, [abandoning its baggage and pressing on day and night to arrive]<ref>[Abandoning its baggage and pressing on day and night to arrive]—supplied from Sun Bin’s Art of War, “Capturing Pang Juan”;", idiomatic: "The Wei army turned back, [abandoning its baggage and marching day and night]<ref>[Abandoning its baggage and marching day and night]—from Sun Bin’s Art of War, “Capturing Pang Juan”;" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "與齊戰-{于}-桂陵，魏師大敗。", literal: "They fought Qi at Guiling; the Wei army was utterly defeated.", idiomatic: "Qi met them at Guiling and routed the Wei army." },
  { zh: "2韓伐東周，取陵觀、廩丘。", literal: "2 Han attacked Eastern Zhou and took Lingguan and Linqiu.", idiomatic: "2 Han attacked Eastern Zhou and took Lingguan and Linqiu." },
  { zh: "3楚昭奚恤爲相。", literal: "3 Zhao Xixu of Chu became chancellor.", idiomatic: "3 Zhao Xixu of Chu became chancellor." },
  { zh: "江乙言-{於}-楚王曰：「人有愛其狗者，狗嘗溺井，其鄰人見，欲入言之，狗當門而噬之。", literal: "Jiang Yi said to the king of Chu, “There was a man who loved his dog. The dog once fouled the well. A neighbor saw it and wished to go in and tell the master, but the dog blocked the door and bit him.", idiomatic: "Jiang Yi said to the king of Chu, “A man loved his dog. The dog fouled the well. A neighbor saw and meant to tell the master, but the dog blocked the door and bit him." },
  { zh: "今昭奚恤常惡臣之見，亦猶是也。", literal: "Now Zhao Xixu constantly resents my audiences with you—it is the same.", idiomatic: "Zhao Xixu hates my coming before you—it is the same." },
  { zh: "且人有好揚人之善者，王曰：『此君子也，』近之；", literal: "Moreover, when someone likes to broadcast others’ good points, you say, ‘This is a gentleman,’ and draw him near;", idiomatic: "When a man likes to spread others’ virtues, you say, ‘This is a gentleman,’ and draw him near;" },
  { zh: "好揚人之惡者，王曰：『此小人也，』遠之。", literal: "when someone likes to broadcast others’ faults, you say, ‘This is a petty man,’ and keep him far.", idiomatic: "when a man likes to spread others’ faults, you say, ‘This is a petty man,’ and keep him far." },
  { zh: "然則且有子弒其父、臣弒其主者，而王終己不知也。", literal: "Then there will be sons who murder their fathers and ministers who murder their lords, yet in the end you will never know.", idiomatic: "Then sons will murder fathers and ministers murder lords, and you will never know." },
  { zh: "何者？", literal: "Why?", idiomatic: "Why?" },
  { zh: "以王好聞人之美而惡聞人之惡也。", literal: "Because you love to hear men’s virtues and hate to hear men’s faults.", idiomatic: "Because you love to hear men praised and hate to hear them blamed." },
  { zh: "」王曰：「善！", literal: "” The king said, “Well said!", idiomatic: "” The king said, “Well said!" },
  { zh: "寡人-{願}-兩聞之。", literal: "I wish to hear both alike.”", idiomatic: "I wish to hear both alike.”" },
  { zh: "〔楚宣王嘗問群臣曰：「吾聞北方之畏昭奚恤也，果誠何如？", literal: "[King Xuan of Chu once asked his ministers, “I hear that the north fears Zhao Xixu—is it really so?", idiomatic: "[King Xuan of Chu once asked his ministers, “I hear the north fears Zhao Xixu—is it true?" },
  { zh: "」群臣莫對。", literal: "” None of the ministers answered.", idiomatic: "” None of the ministers answered." },
  { zh: "江乙對曰：「虎求百獸而食之，得狐。", literal: "Jiang Yi answered, “A tiger sought the hundred beasts to devour them and caught a fox.", idiomatic: "Jiang Yi answered, “A tiger hunted the beasts to eat them and caught a fox." },
  { zh: "狐曰：『子無敢食我也。", literal: "The fox said, ‘You dare not eat me.", idiomatic: "The fox said, ‘You dare not eat me." },
  { zh: "天帝使我長百獸，今子食我，是逆天帝命也。", literal: "Heaven’s Lord made me chief of the hundred beasts; if you eat me now, you defy Heaven’s Lord’s command.", idiomatic: "Heaven made me lord of the beasts; eat me now and you defy Heaven." },
  { zh: "子以我爲不信，吾爲子先行，子隨我-{後}-，觀百獸之見我而敢不走乎？", literal: "If you think me untrustworthy, I will go ahead for you; follow behind me and see whether any beast dares not flee when it sees me.", idiomatic: "If you doubt me, I will walk ahead; follow behind and see whether any beast dares not flee at sight of me." },
  { zh: "』虎以爲然，故遂與之行。", literal: "’ The tiger thought this right and so walked with him.", idiomatic: "’ The tiger believed him and walked with him." },
  { zh: "獸見之皆走。", literal: "The beasts that saw them all fled.", idiomatic: "Every beast they met fled." },
  { zh: "虎不知獸畏己而走也，以爲畏狐也。", literal: "The tiger did not know the beasts fled from fear of himself; he thought they feared the fox.", idiomatic: "The tiger did not know the beasts feared him; he thought they feared the fox." },
  { zh: "今王之地方五千-{里}-，帶甲百萬，而專屬之昭奚恤；", literal: "Now your territory is five thousand li, your armored men a million, yet you entrust all to Zhao Xixu;", idiomatic: "Your realm is five thousand li, your armored men a million, yet you entrust all to Zhao Xixu;" },
  { zh: "故北方之畏奚恤也，其實畏王之甲兵也，猶百獸之畏虎也。", literal: "so when the north fears Xixu, it truly fears your majesty’s armor and weapons, as the hundred beasts fear the tiger.", idiomatic: "so when the north fears Xixu, it truly fears your majesty’s arms, as the beasts fear the tiger." },
  { zh: "」〕<ref>〔楚宣王嘗問群臣曰〕句-{據}-《戰國策·楚策一》第三章補。", literal: "”]<ref>The clause [King Xuan of Chu once asked his ministers]—supplied from Strategies of the Warring States, Chu Stratagems 1, chapter 3;", idiomatic: "”]<ref>The clause [King Xuan of Chu once asked his ministers]—from Strategies of the Warring States, Chu Stratagems 1, chapter 3;" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "4〔宋景善、衞公孫倉會齊師〕(", literal: "4 [Song Jingshan and Gongsun Cang of Wei joined the Qi army](", idiomatic: "4 [Song Jingshan and Gongsun Cang of Wei joined the Qi army](" },
  { zh: "諸侯)", literal: "the feudal lords)", idiomatic: "the allied lords)" },
  { zh: "，圍魏襄陵<ref>〔宋景善衞公孫倉會齊師〕(", literal: ", and besieged Xiangling in Wei<ref>[Song Jingshan and Gongsun Cang of Wei joined the Qi army](", idiomatic: ", and besieged Xiangling in Wei<ref>[Song Jingshan and Gongsun Cang of Wei joined the Qi army](" },
  { zh: "諸侯)", literal: "the feudal lords)", idiomatic: "the allied lords)" },
  { zh: "本-{繫}--{於}-周顯王十七年，-{據}-《水經·淮水注》改-{並}-移入此年。", literal: "originally placed under the seventeenth year of King Xian of Zhou; changed and moved to this year according to the Commentary on the Huai River in the Water Classic;", idiomatic: "originally dated to King Xian’s seventeenth year; revised and moved to this year per the Huai River commentary in the Water Classic;" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1〔魏以韓師敗諸侯-{於}-襄陵。", literal: "1 [With Han’s troops Wei defeated the allied lords at Xiangling.", idiomatic: "1 [With Han’s troops Wei defeated the allied lords at Xiangling." },
  { zh: "齊使楚景-{舍}-來求和。", literal: "Qi sent Chu’s Jing She to sue for peace.", idiomatic: "Qi sent Jing She of Chu to sue for peace." },
  { zh: "魏惠王會齊、宋之圍〕<ref>〔魏以韓師敗諸侯-{於}-襄陵〕句-{據}-《水經·淮水注》引《紀年》補。", literal: "King Hui of Wei joined Qi and Song in raising the siege]<ref>The clause [With Han’s troops Wei defeated the allied lords at Xiangling]—supplied from the Bamboo Annals cited in the Huai River commentary in the Water Classic;", idiomatic: "King Hui of Wei joined Qi and Song in lifting the siege]<ref>The clause [With Han’s troops Wei defeated the allied lords at Xiangling]—from the Bamboo Annals in the Huai River commentary;" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2秦大良造〔衞鞅〕伐魏，〔圍安邑，降之〕<ref>秦大良造〔衞鞅〕伐魏〔圍安邑降之〕-{據}-胡注及《史記·秦本紀》補。", literal: "2 Qin’s Grandee Counselor [Wei Yang] attacked Wei, [besieged Anyi, and received its surrender]<ref>Qin’s Grandee Counselor [Wei Yang] attacked Wei [besieged Anyi and received its surrender]—supplied from Hu’s commentary and Shiji “Basic Annals of Qin”;", idiomatic: "2 Qin’s Grandee Counselor [Wei Yang] attacked Wei, [besieged Anyi, and took its surrender]<ref>Qin’s Grandee Counselor [Wei Yang] attacked Wei [besieged Anyi and took its surrender]—from Hu’s commentary and Shiji “Basic Annals of Qin”;" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "3〔魯共公薨，子康公毛立〕<ref>〔魯共公薨子康公毛立〕舊文-{繫}--{於}-顯王十四年，今-{據}-近人考-{証}-移入此年</ref>。", literal: "3 [Duke Gong of Lu died; his son Duke Kang Mao succeeded]<ref>[Duke Gong of Lu died and Duke Kang Mao succeeded]—the old text was placed under the fourteenth year of King Xian; now moved to this year on modern scholars’ textual proof</ref>.", idiomatic: "3 [Duke Gong of Lu died; his son Duke Kang Mao succeeded]<ref>[Duke Gong of Lu died and Duke Kang Mao succeeded]—formerly dated to King Xian’s fourteenth year; moved to this year on modern textual proof</ref>." },
  { zh: "1秦衞鞅圍魏固陽，降之。", literal: "1 Wei Yang of Qin besieged Guyang in Wei and received its surrender.", idiomatic: "1 Wei Yang of Qin besieged Guyang in Wei and took its surrender." },
  { zh: "2魏人歸趙邯鄲，與趙盟漳水上。", literal: "2 The men of Wei returned Handan to Zhao and allied with Zhao on the Zhang River.", idiomatic: "2 Wei returned Handan to Zhao and made alliance with Zhao on the Zhang River." },
  { zh: "3韓昭侯以申不害爲相。", literal: "3 Marquis Zhao of Han made Shen Buhai chancellor.", idiomatic: "3 Marquis Zhao of Han made Shen Buhai chancellor." },
  { zh: "申不害者，鄭之賤臣也，學黃、老、刑名，以-{干}-昭侯。", literal: "Shen Buhai was a low minister of Zheng who studied Huang-Lao and the school of names and sought audience with Marquis Zhao.", idiomatic: "Shen Buhai was a humble minister of Zheng who studied Huang-Lao and legalism and sought office with Marquis Zhao." },
  { zh: "昭侯用爲相，内修政教，外應諸侯，十五年，終申子之身，國治兵強。", literal: "Marquis Zhao employed him as chancellor; within he cultivated government and teaching, without he answered the feudal lords—for fifteen years, to the end of Master Shen’s life, the state was well governed and its arms strong.", idiomatic: "Marquis Zhao made him chancellor; within he ordered government and teaching, without he met the feudal lords—for fifteen years, while Master Shen lived, the state was well ruled and its arms strong." },
  { zh: "申子嘗請仕其從兄，昭侯不許，申子有怨色。", literal: "Master Shen once asked that his paternal cousin be given office; Marquis Zhao refused, and Master Shen showed resentment.", idiomatic: "Master Shen once asked office for a cousin; Marquis Zhao refused, and Master Shen showed resentment." },
  { zh: "昭侯曰：「所爲學-{於}-子者，欲以治國也。", literal: "Marquis Zhao said, “What I studied with you for was to govern the state.", idiomatic: "Marquis Zhao said, “I studied with you to govern the state." },
  { zh: "今將-{聽}-子之謁而廢子之-{術}-乎，已其行子之-{術}-而廢子之請乎？", literal: "Now shall I heed your plea and abandon your methods, or practice your methods and abandon your plea?", idiomatic: "Shall I heed your plea and abandon your methods, or practice your methods and set your plea aside?" },
  { zh: "子嘗教寡人修功勞，視次第；", literal: "You once taught me to rank merit and regard order of precedence;", idiomatic: "You taught me to rank merit and honor precedence;" },
  { zh: "今有所私求，我將奚-{聽}-乎？", literal: "now there is a private request—whom shall I heed?”", idiomatic: "now you make a private request—whom shall I heed?”" },
  { zh: "」申子乃-{辟}--{舍}-請罪曰：「君眞其人也。", literal: "” Master Shen then withdrew from his mat to ask pardon, saying, “My lord is truly the man for this.", idiomatic: "” Master Shen withdrew from his mat to ask pardon: “My lord is truly the man for this." },
  { zh: "」昭侯有弊袴，命藏之。", literal: "” Marquis Zhao had worn-out trousers and ordered them stored away.", idiomatic: "” Marquis Zhao had worn trousers and ordered them stored." },
  { zh: "侍者曰：「君亦不仁者矣。", literal: "An attendant said, “My lord is unkind indeed.", idiomatic: "An attendant said, “My lord is hardly kind." },
  { zh: "不賜左右而藏之！", literal: "You do not give them to those at your side but hide them away!”", idiomatic: "You will not give them to your attendants but hide them away!”" },
  { zh: "」昭侯曰：「吾聞明主愛一嚬一笑，嚬有爲嚬，笑有爲笑。", literal: "” Marquis Zhao said, “I have heard that an enlightened ruler cherishes each frown and smile—a frown has its occasion, a smile its occasion.", idiomatic: "” Marquis Zhao said, “I have heard that an enlightened ruler values each frown and smile—each frown has its cause, each smile its cause." },
  { zh: "今胯豈特嚬笑哉！", literal: "Now trousers are surely more than a frown or smile!", idiomatic: "Trousers are more than a frown or smile!" },
  { zh: "吾必待有功者。", literal: "I must wait for one who has merit.”", idiomatic: "I must wait for one who has earned merit.”" },
  { zh: "1秦商鞅-{築}-冀闕宮庭-{於}--{咸}-陽，徙都之。", literal: "1 Shang Yang of Qin built the Que Gate palace at Xianyang and moved the capital there.", idiomatic: "1 Shang Yang of Qin built the Que Gate palace at Xianyang and moved the capital there." },
  { zh: "令民父子、兄弟同室内息者爲禁。", literal: "He forbade fathers and sons or brothers to dwell and rest in the same inner room.", idiomatic: "He forbade fathers and sons or brothers to share one inner room for lodging." },
  { zh: "-{並}-諸小鄕聚集爲一縣，縣置令、丞，凡三十一縣。", literal: "He merged the small hamlets into single counties, set a magistrate and assistant in each county—in all thirty-one counties.", idiomatic: "He merged small hamlets into counties, set a magistrate and assistant in each—in all thirty-one counties." },
  { zh: "廢井田，開阡陌，平-{斗}-、〔甬〕(", literal: "He abolished the well-field system, opened the field paths, and standardized the dou and [yong](", idiomatic: "He abolished the well-field system, opened the field paths, and standardized the dou and [yong](" },
  { zh: "桶)", literal: "bucket),", idiomatic: "bucket)," },
  { zh: "、權、衡、丈、尺<ref>平-{斗}-〔甬〕(", literal: "weights, steelyards, and the foot and inch measures<ref>Standardize the dou and [yong](", idiomatic: "weights, steelyards, and the foot and inch<ref>Standardize the dou and [yong](" },
  { zh: "桶)", literal: "bucket)", idiomatic: "bucket)" },
  { zh: "權衡丈尺-{據}-胡注改。", literal: "weights, steelyards, foot and inch—changed per Hu’s commentary.", idiomatic: "weights, steelyards, foot and inch—revised per Hu’s commentary." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2秦、魏〔會〕(", literal: "2 Qin and Wei [met](", idiomatic: "2 Qin and Wei [met](" },
  { zh: "遇)", literal: "encountered)", idiomatic: "encountered)" },
  { zh: "-{于}-彤<ref>秦魏〔會〕(", literal: "at Tong<ref>Qin and Wei [met](", idiomatic: "at Tong<ref>Qin and Wei [met](" },
  { zh: "遇)", literal: "encountered)", idiomatic: "encountered)" },
  { zh: "-{于}-彤-{據}-《史記·六國年表》及《魏世家》改。", literal: "at Tong—changed according to Shiji “Chronological Table of the Six States” and “House of Wei”.", idiomatic: "at Tong—revised per Shiji “Chronological Table of the Six States” and “House of Wei”." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "3趙成侯薨，公子諜與太子〔語〕爭。", literal: "3 Marquis Cheng of Zhao died; the lordling Die contended with the heir [Yu] for the succession.", idiomatic: "3 Marquis Cheng of Zhao died; the lordling Die contended with the heir [Yu] for the throne." },
  { zh: "立諜敗，奔韓。", literal: "Die was set up, was defeated, and fled to Han.", idiomatic: "Die was enthroned, was defeated, and fled to Han." },
  { zh: "〔太子立，是爲肅侯〕<ref>公子諜與太子〔語〕爭立立諜敗奔韓〔太子立是爲肅侯〕-{據}-《史記·趙世家》索隱引《世本》補。", literal: "[The heir was enthroned; this was Marquis Su]<ref>Lordling Die contended with the heir [Yu] for enthronement; Die was set up, was defeated, and fled to Han; [the heir was enthroned; this was Marquis Su]—supplied from Shiji “House of Zhao,” Suoyin citing Shiben;", idiomatic: "[The heir was enthroned as Marquis Su]<ref>Lordling Die contended with the heir [Yu]; Die was enthroned, was defeated, and fled to Han; [the heir was enthroned as Marquis Su]—from Shiji “House of Zhao,” Suoyin citing Shiben;" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "4〔宋剔城廢其君而自立〕<ref>〔宋剔城廢其君而自立〕舊文爲「宋-{辟}-公薨，子剔成立」，本-{繫}--{於}-安王六年，今移入此年，-{並}--{據}-《史記·宋世家》索隱王劭引《紀年》改。", literal: "4 [Ticheng of Song deposed his lord and set himself up]<ref>[Ticheng of Song deposed his lord and set himself up]—the old text read “Duke Pi of Song died; his son Ticheng succeeded,” originally placed under the sixth year of King An; now moved to this year and changed according to Wang Shao’s citation of the Bamboo Annals in Shiji “House of Song,” Suoyin</ref>.", idiomatic: "4 [Ticheng of Song deposed his lord and made himself ruler]<ref>[Ticheng of Song deposed his lord and made himself ruler]—formerly “Duke Pi of Song died; his son Ticheng succeeded,” dated to King An’s sixth year; moved here and revised per Wang Shao’s Bamboo Annals in Shiji “House of Song,” Suoyin</ref>." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1〔秦初爲賦〕<ref>〔秦初爲賦〕舊作「秦商鞅更爲賦稅法，行之」，-{據}-《史記·秦世家》改。", literal: "1 [Qin first instituted the fu levy]<ref>[Qin first instituted the fu levy] formerly read “Qin’s Lord Shang Yang revised the fu-tax law and put it into effect”; changed per Shiji “House of Qin.”", idiomatic: "1 [Qin first instituted the fu levy]<ref>[Qin first instituted the fu levy]—formerly “Qin’s Lord Shang Yang revised the fu-tax law and enacted it”; changed per Shiji “House of Qin.”" },
  { zh: "案：-{據}-今人考-{証}-，此賦蓋指初-{徴}-戸賦，司馬光誤以爲更賦稅法。", literal: "Note: according to modern scholars’ research, this fu probably refers to the first household levy; Sima Guang mistakenly took it for a revision of the fu-tax law.", idiomatic: "Note: modern scholarship holds this fu was the first household levy; Sima Guang mistook it for a revised fu-tax code." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2〔齊威王來朝。", literal: "2 [King Wei of Qi came to court.", idiomatic: "2 [King Wei of Qi came to court." },
  { zh: "是時周室微弱，諸侯莫朝，而齊獨朝之，天下以此益賢威王〕<ref>〔齊威王來朝〕句此段本-{繫}--{於}-上巻周烈王六年，今移入此年。", literal: "At that time the Zhou house was feeble; none of the feudal lords came to court, yet Qi alone did so, and All-under-Heaven thereby esteemed King Wei all the more]<ref>The passage [King Wei of Qi came to court] was originally attached to year six of King Lie of Zhou in the previous scroll; it is moved to this year.", idiomatic: "The Zhou house was weak; no feudal lord came to court but Qi, and the realm esteemed King Wei all the more for it]<ref>[King Wei of Qi came to court]—this passage was tied to year six of King Lie of Zhou in the prior scroll; moved to this year." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1趙公子-{范}-襲邯鄲，不勝而死。", literal: "1 The Zhao lord Fan attacked Handan, failed to win, and died.", idiomatic: "1 Prince Fan of Zhao raided Handan, was defeated, and died." },
  { zh: "1齊殺其大夫牟〔辛〕<ref>牟〔辛〕-{據}-《史記·田世家》補。", literal: "1 Qi killed its grandee Mou [Xin]<ref>Mou [Xin]—supplied from Shiji “House of Tian.”", idiomatic: "1 Qi executed its minister Mou [Xin]<ref>Mou [Xin]—from Shiji “House of Tian.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2魯康公薨，子景公偃立。", literal: "2 Duke Kang of Lu died; his son Duke Jing, Yan, succeeded.", idiomatic: "2 Duke Kang of Lu died; his son Duke Jing Yan succeeded." },
  { zh: "3衞更貶號曰侯，服屬三晉。", literal: "3 Wei further reduced its title to marquis and submitted to the Three Jin.", idiomatic: "3 Wei was demoted again to marquis and acknowledged the Three Jin as overlords." },
  { zh: "1諸侯會-{于}-京師。", literal: "1 The feudal lords assembled at the capital.", idiomatic: "1 The feudal lords gathered at the royal capital." },
  { zh: "〔秦孝公使公子少官帥師會諸侯，以朝王〕<ref>〔秦孝公〕句以下本-{繫}--{於}-周顯王二十六年，-{據}-楊寬《戰國史料編年輯-{証}-》考訂移入此年，-{並}-刪「-{于}-逢潭」三字。", literal: "[Duke Xiao of Qin sent the young lord Shaoguan to lead troops to join the feudal lords in paying court to the king]<ref>The passage beginning [Duke Xiao of Qin] was originally attached to year twenty-six of King Xian of Zhou; moved to this year per Yang Kuan’s Collation of Warring States Historical Materials, and the three characters “at Fengtan” deleted.", idiomatic: "[Duke Xiao of Qin sent Prince Shaoguan at the head of an army to join the lords in audience with the king]<ref>From [Duke Xiao of Qin] onward was tied to year twenty-six of King Xian of Zhou; moved here per Yang Kuan’s Warring States chronology, deleting “at Fengtan.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1王致伯-{于}-秦，諸侯皆賀秦。", literal: "1 The king invested Qin as a hegemon; all the feudal lords congratulated Qin.", idiomatic: "1 The king named Qin hegemon; every feudal lord sent congratulations." },
  { zh: "2〔越無顓薨，子無彊立〕<ref>〔越無顓薨子無彊立〕此段-{據}-《史記·越世家》索隱引《紀年》補，依楊寬《戰國史料編年輯-{証}-》越君年世之考訂-{繫}--{於}-此年。", literal: "2 [Wuzhuan of Yue died; his son Wujiang succeeded]<ref>[Wuzhuan of Yue died; Wujiang succeeded]—this passage supplied from Shiji “House of Yue,” Suoyin citing the Bamboo Annals; attached to this year per Yang Kuan’s chronology of Yue rulers in his Collation of Warring States Historical Materials.", idiomatic: "2 [King Wuzhuan of Yue died; his son Wujiang succeeded]<ref>[Wuzhuan of Yue died; Wujiang succeeded]—from Shiji “House of Yue,” Suoyin citing the Bamboo Annals; dated to this year per Yang Kuan’s Yue ruler chronology." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1魏龐涓伐韓。", literal: "1 Pang Juan of Wei attacked Han.", idiomatic: "1 Pang Juan of Wei invaded Han." },
  { zh: "韓請救-{於}-齊。", literal: "Han asked Qi for rescue.", idiomatic: "Han begged Qi for aid." },
  { zh: "齊威王召大臣而謀曰：「蚤救孰與晩救？", literal: "King Wei of Qi summoned his ministers to deliberate and said, “Which is better—to rescue early or late?”", idiomatic: "King Wei of Qi called his ministers and asked, “Is it better to rescue early or late?”" },
  { zh: "」成侯曰：「不如勿救。", literal: "” Marquis Cheng said, “Better not to rescue at all.", idiomatic: "” Marquis Cheng said, “Better not to intervene." },
  { zh: "」田忌曰：「弗救則韓且折而入-{於}-魏，不如蚤救之。", literal: "” Tian Ji said, “If we do not rescue, Han will soon break and fall to Wei; better to rescue early.”", idiomatic: "” Tian Ji said, “If we hold back, Han will buckle into Wei’s hands—better rescue at once.”" },
  { zh: "」孫臏曰：「夫韓、魏之兵未弊而救之，是吾代韓受魏之兵，顧反-{聽}-命-{於}-韓也。", literal: "” Sun Bin said, “If we rescue while Han and Wei’s troops are not yet exhausted, we take Wei’s blows for Han and in the end must obey Han’s orders.", idiomatic: "” Sun Bin said, “Rescue before their armies are spent and we absorb Wei’s blows for Han—then turn and take orders from Han." },
  { zh: "且魏有破國之-{志}-，韓見亡，必東-{面}-而愬-{於}-齊矣。", literal: "Moreover Wei has the will to crush a state; when Han sees itself perishing, it is sure to turn east and plead to Qi.", idiomatic: "Wei means to destroy a kingdom; when Han faces ruin it will turn east and plead to us." },
  { zh: "吾因深結韓之親而晩承魏之弊，則可受重利而得尊名也。", literal: "If we therefore bind Han close in friendship and only later take up Wei’s exhaustion, we may gain great profit and a noble name.”", idiomatic: "Bind Han to us in secret, strike only after Wei is worn down, and we gain rich profit and a great name.”" },
  { zh: "」王曰：「善！", literal: "” The king said, “Excellent!”", idiomatic: "” The king said, “Good!”" },
  { zh: "」乃陰許韓使而遣之。", literal: "” He then secretly promised Han’s envoy and sent him away.", idiomatic: "” He secretly assured Han’s envoy and dismissed him." },
  { zh: "韓因恃齊，五戰不勝，而東委國-{於}-齊。", literal: "Han, relying on Qi, fought five battles without victory and then turned east to entrust the state to Qi.", idiomatic: "Trusting Qi, Han fought five losing battles and then turned east to place the state in Qi’s hands." },
  { zh: "齊因起兵，使田忌、田嬰、田盻將之，孫子爲師，以救韓，直走魏都。", literal: "Qi thereupon raised troops, appointing Tian Ji, Tian Ying, and Tian Pan as generals with Master Sun as strategist, to rescue Han by marching straight on Wei’s capital.", idiomatic: "Qi mobilized, with Tian Ji, Tian Ying, and Tian Pan in command and Master Sun as strategist, marching not to relieve Han but straight for Wei’s capital." },
  { zh: "龐涓聞之，去韓而歸。", literal: "Pang Juan heard and left Han to return.", idiomatic: "Pang Juan heard and quit Han to hurry home." },
  { zh: "魏人大-{發}-兵，以太子申爲將，以-{御}-齊師。", literal: "Wei mustered a great army, making the crown prince Shen general to meet the army of Qi.", idiomatic: "Wei raised a great host and made Crown Prince Shen general to face Qi." },
  { zh: "孫子謂田忌曰：「彼三晉之兵素悍勇而輕齊，齊號爲怯。", literal: "Master Sun said to Tian Ji, “The troops of the Three Jin are by nature fierce and brave and despise Qi; Qi is known as cowardly.", idiomatic: "Sun Bin told Tian Ji, “Jin’s warriors are fierce and hold Qi in contempt; Qi is reputed timid." },
  { zh: "善戰者因其勢而利導之。", literal: "A skilled fighter bends their momentum to his advantage.", idiomatic: "A true commander steers their momentum to his profit." },
  { zh: "《兵法》：『百-{里}-而趣利者蹶上將，五十-{里}-而趣利者軍半至。", literal: "The Art of War says: ‘He who races a hundred li for gain will cripple his leading general; he who races fifty li will bring only half his army.’", idiomatic: "The Art of War says: ‘Rush a hundred li for gain and the foremost general stumbles; rush fifty li and half the army never arrives.’" },
  { zh: "』」乃使齊軍入魏地爲十萬竈，明日爲五萬竈，又明日爲二萬竈。", literal: "’” He then had the Qi army, upon entering Wei territory, make one hundred thousand cooking pits; the next day fifty thousand; the day after twenty thousand.", idiomatic: "’” He had Qi’s army light stoves for a hundred thousand men in Wei soil, then fifty thousand the next day, then twenty thousand." },
  { zh: "龐涓行三日，大喜曰：「我固知齊軍怯，入吾地三日，士卒亡者過半矣！", literal: "Pang Juan marched three days and said in great joy, “I knew the Qi army was cowardly! Three days in our land and more than half the soldiers have fled!”", idiomatic: "After three days’ march Pang Juan exulted: “I knew Qi was timid—three days in our land and more than half their men have deserted!”" },
  { zh: "」乃棄其歩軍，與其輕鋭倍日-{並}-行逐之。", literal: "” He then abandoned his infantry and, with picked light troops, pressed the pursuit at double the day’s march.", idiomatic: "” He left his foot soldiers behind and drove on with elite light troops at twice the normal pace." },
  { zh: "孫子度其行，暮當至馬陵。", literal: "Master Sun estimated their march: at dusk they should reach Maling.", idiomatic: "Sun Bin reckoned their pace: by evening they would reach Maling." },
  { zh: "馬陵道狹而旁多阻隘，可伏兵。", literal: "The road at Maling was narrow with many obstacles on either side—ideal for an ambush.", idiomatic: "Maling’s pass was narrow, the flanks choked with obstacles—perfect ground for an ambush." },
  { zh: "乃斫大樹，白而書之曰：「龐涓死此樹下！", literal: "He had a great tree stripped and wrote on the white wood: “Pang Juan dies beneath this tree!”", idiomatic: "He stripped a great tree and wrote on the bare wood: “Pang Juan dies beneath this tree!”" },
  { zh: "」-{於}-是令齊師善射者萬弩夾道而伏，期〔曰〕(", literal: "” He then stationed ten thousand skilled archers of Qi along the road in ambush, with the signal [said] (", idiomatic: "” He posted ten thousand of Qi’s best archers along the road, the signal [said] (" },
  { zh: "日)", literal: "day)", idiomatic: "day)" },
  { zh: "<ref>期〔曰〕(", literal: "<ref>The signal [said] (", idiomatic: "<ref>The signal [said] (" },
  { zh: "日)", literal: "day)", idiomatic: "day)" },
  { zh: "-{據}-《史記·孫子列傳》改。", literal: "-{collated}-per Shiji “Biography of Sunzi,” changed.", idiomatic: "changed per Shiji “Biography of Sunzi.”" },
  { zh: "</ref>：「暮見火舉而倶-{發}-。", literal: "</ref>: “At dusk, when you see torches raised, shoot all together.”", idiomatic: "</ref>: “At dusk, when torches flare, loose every bow together.”" },
  { zh: "」龐涓果夜到斫木下，見白書，以火燭之。", literal: "” Pang Juan did come by night to the felled tree, saw the white writing, and held a torch to read it.", idiomatic: "” Pang Juan came by night to the cut tree, saw the pale inscription, and raised a torch to read." },
  { zh: "讀未畢，萬弩倶-{發}-，魏師大亂相失。", literal: "Before he finished reading, ten thousand crossbows shot together; the Wei army fell into great disorder and men lost one another.", idiomatic: "Before he finished, ten thousand bolts flew; Wei’s host broke apart in chaos." },
  { zh: "龐涓自知智窮兵敗，乃自剄，曰：「遂成豎子之名！", literal: "Pang Juan knew his stratagems were exhausted and his army defeated; he cut his own throat and said, “So this brat wins his fame!”", idiomatic: "Knowing himself beaten, Pang Juan cut his throat: “Now the stripling wins his name!”" },
  { zh: "」齊因乘勝大破魏師，虜太子申。", literal: "” Qi then pressed the victory, routed the Wei army utterly, and captured Crown Prince Shen.", idiomatic: "” Qi swept on, shattered Wei’s army, and took Crown Prince Shen prisoner." },
  { zh: "2成侯鄒忌惡田忌，使人操十金，-{卜}--{於}-市，曰：「我，田忌之人也。", literal: "2 Marquis Cheng Zou Ji hated Tian Ji and sent a man with ten pieces of gold to divine in the market, saying, “I am Tian Ji’s man.", idiomatic: "2 Marquis Cheng Zou Ji resented Tian Ji and sent a man with ten gold pieces to the diviners in the market, saying, “I serve Tian Ji." },
  { zh: "我爲將三戰三勝，〔聲威天下〕<ref>〔聲威天下〕-{據}-《史記·田世家》及《戰國策·齊策一》補。", literal: "I have been general in three battles and three victories, [my fame shaking the realm]<ref>[my fame shaking the realm]—supplied from Shiji “House of Tian” and Strategies of the Warring States, Qi Strategy 1.", idiomatic: "Three battles, three victories as general, [my fame filling the realm]<ref>[my fame filling the realm]—from Shiji “House of Tian” and Strategies of the Warring States, Qi Strategy 1." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "欲行大事，可乎？", literal: "I wish to undertake a great enterprise—will it succeed?”", idiomatic: "I mean to attempt a great coup—will it succeed?”" },
  { zh: "」-{卜}-者出，因使人執之。", literal: "” When the diviner came out, he had the man seized.", idiomatic: "” As the diviner left, agents seized him." },
  { zh: "田忌不能自明，率其徒攻臨淄，求成侯。", literal: "Tian Ji could not clear himself; he led his followers to attack Linzi and sought Marquis Cheng.", idiomatic: "Tian Ji could not vindicate himself and led his men against Linzi to seize Marquis Cheng." },
  { zh: "不克，出奔楚。", literal: "He did not prevail and fled to Chu.", idiomatic: "He failed and fled to Chu." },
  { zh: "1衞鞅言-{於}-秦孝公曰：「秦之與魏，譬若人之有腹心之疾，非魏-{並}-秦，秦卽-{並}-魏。", literal: "1 Lord Wei Yang said to Duke Xiao of Qin, “Qin and Wei are like a man with a disease in his vitals: if Wei does not swallow Qin, Qin will swallow Wei.", idiomatic: "1 Lord Wei Yang told Duke Xiao of Qin, “Qin and Wei are like a man with a sickness at the heart: unless Wei devours Qin, Qin will devour Wei." },
  { zh: "何者？", literal: "Why?", idiomatic: "Why?" },
  { zh: "魏居嶺阨之西<ref>魏居嶺阨之西下本有正文「都安邑」三字，案魏遷都大梁乃周顯王八年事，今刪之。", literal: "Wei lies west of the mountain passes<ref>After “Wei lies west of the mountain passes” the main text originally had the three characters “with its capital at Anyi”; as Wei’s move to Daliang belongs to year eight of King Xian of Zhou, these are now deleted.", idiomatic: "Wei sits west of the passes<ref>After “west of the passes” the text once read “capital at Anyi”; Wei’s move to Daliang belongs to year eight of King Xian of Zhou and is deleted here." },
  { zh: "</ref>，與秦界河，而獨擅山東之利。", literal: "</ref>, shares a river border with Qin, and alone monopolizes the profits of the lands east of the mountains.", idiomatic: "</ref>, borders Qin along the river, and alone holds the wealth of the lands east of the mountains." },
  { zh: "利則西侵秦，病則東收地。", literal: "When strong it invades Qin to the west; when weak it gathers territory to the east.", idiomatic: "In strength it raids west into Qin; in weakness it swallows lands to the east." },
  { zh: "今以君之賢聖，國賴以盛；", literal: "Now with your worth and sagacity the state relies on you and flourishes;", idiomatic: "Under your wisdom the state thrives;" },
  { zh: "而魏往年大破-{於}-齊，諸侯畔之，可因此時伐魏。", literal: "while Wei was routed by Qi in recent years and the feudal lords have turned from it—one may take this moment to attack Wei.", idiomatic: "Wei was shattered by Qi not long ago and the lords have deserted it—strike now." },
  { zh: "魏不支秦，必東徙。", literal: "Wei cannot withstand Qin and is sure to move east.", idiomatic: "Wei cannot stand against Qin and will shift east." },
  { zh: "然-{後}-秦-{據}-河山之固，東鄕以-{制}-諸侯，此帝王之業也。", literal: "Then Qin will hold the strength of river and mountain and turn east to command the feudal lords—this is the enterprise of a true king.”", idiomatic: "Then Qin will grip the river-and-mountain barrier and face east to rule the lords—the work of an emperor.”" },
  { zh: "」公從之，使衞鞅將兵伐魏。", literal: "” The duke followed his counsel and sent Lord Wei Yang to lead troops against Wei.", idiomatic: "” The duke agreed and sent Lord Wei Yang against Wei." },
  { zh: "魏使公子卬將而-{禦}-之。", literal: "Wei sent the young lord Ang as general to meet him.", idiomatic: "Wei sent Prince Ang to oppose him." },
  { zh: "軍旣相距，衞鞅遺公子卬書曰：「吾始與公子歡，今倶爲兩國將，不忍相攻，可與公子-{面}-相見盟，樂飲而罷兵，以安秦、魏之民。", literal: "When the armies had faced each other, Wei Yang sent Prince Ang a letter: “I began in friendship with you; now we are both generals of two states. I cannot bear mutual attack. Let us meet face to face and covenant, drink in pleasure, and disband the armies to settle the people of Qin and Wei.”", idiomatic: "As the armies faced each other, Wei Yang wrote Prince Ang: “We were friends once; now we command rival hosts. I cannot bear to fight you—meet me, let us pledge over wine and send the armies home in peace for Qin and Wei.”" },
  { zh: "」公子卬以爲然，乃相與會。", literal: "” Prince Ang thought this right and met with him.", idiomatic: "” Prince Ang agreed and came to the parley." },
  { zh: "盟已，飲。", literal: "When the covenant was done, they drank.", idiomatic: "They pledged, then drank." },
  { zh: "而衞鞅伏甲士，襲虜公子卬，因攻魏師，大破之。", literal: "But Wei Yang had armored men in hiding; he struck, captured Prince Ang, and attacked the Wei army, routing it utterly.", idiomatic: "Wei Yang had hidden swordsmen; they seized Prince Ang, and he fell on Wei’s army and broke it." },
  { zh: "魏惠王恐，使使獻河西之地-{於}-秦以和<ref>使使獻河西之地-{於}-秦以和下本有正文「因去安邑徙都大梁乃」九字，案魏遷都大梁乃周顯王八年事，此刪之。", literal: "King Hui of Wei was afraid and sent envoys to offer the lands west of the river to Qin for peace<ref>After “sent envoys to offer the lands west of the river to Qin for peace” the main text originally had nine characters, “thereupon leaving Anyi and moving the capital to Daliang”; as Wei’s move to Daliang belongs to year eight of King Xian of Zhou, these are deleted here.", idiomatic: "King Hui of Wei in fear sent envoys to cede the lands west of the river for peace<ref>After “for peace” the text once read “then left Anyi and moved the capital to Daliang”; Wei’s move to Daliang belongs to year eight of King Xian of Zhou and is deleted." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "歎曰：「吾恨不用公叔之言！", literal: "He sighed and said, “I regret not heeding Gongsun’s words!”", idiomatic: "He sighed: “I regret not taking Gongsun’s counsel!”" },
  { zh: "秦封衞鞅商-{於}-十五邑，號曰商君。", literal: "Qin enfeoffed Lord Wei Yang with fifteen towns in Shang and styled him Lord Shang.", idiomatic: "Qin granted Lord Wei Yang fifteen towns in Shang and titled him Lord Shang." },
  { zh: "2齊、趙〔會博望〕<ref>〔會博望〕-{據}-《史記·田世家》集解徐廣引《六國年表》補。", literal: "2 Qi and Zhao [met at Bowang]<ref>[met at Bowang]—supplied from Shiji “House of Tian,” Jijie, Xu Guang citing the “Table by Reign of the Six States.”", idiomatic: "2 Qi and Zhao [met at Bowang]<ref>[met at Bowang]—from Shiji “House of Tian,” Jijie, Xu Guang citing the “Table by Reign of the Six States.”" },
  { zh: "</ref>，伐魏。", literal: "</ref> and attacked Wei.", idiomatic: "</ref> and attacked Wei." },
  { zh: "3楚宣王薨，子威王商立。", literal: "3 King Xuan of Chu died; his son King Wei, Shang, succeeded.", idiomatic: "3 King Xuan of Chu died; his son King Wei Shang succeeded." },
  { zh: "1秦孝公薨，子惠文王立，公子虔之徒告商君欲反，-{發}-吏捕之。", literal: "1 Duke Xiao of Qin died; his son King Huiwen succeeded. The faction of the young lord Qian accused the Lord of Shang of plotting rebellion, and officers were sent to arrest him.", idiomatic: "1 Duke Xiao of Qin died; his son King Huiwen took the throne. Prince Qian’s party accused the Lord of Shang of treason, and officers were sent to seize him." },
  { zh: "商君亡之魏。", literal: "The Lord of Shang fled to Wei.", idiomatic: "The Lord of Shang fled to Wei." },
  { zh: "魏人不受，-{復}-内之秦。", literal: "The men of Wei would not receive him and sent him back into Qin.", idiomatic: "Wei would not shelter him and handed him back to Qin." },
  { zh: "商君乃與其徒之商-{於}-，-{發}-兵北撃鄭。", literal: "The Lord of Shang then went with his followers to Shang and raised troops to strike Zheng from the north.", idiomatic: "He went with his followers to his fief in Shang and raised troops to attack Zheng from the north." },
  { zh: "秦人攻商君，殺之，車裂以徇，盡滅其家。", literal: "The men of Qin attacked the Lord of Shang, killed him, dismembered his corpse by chariots as a public warning, and exterminated his entire clan.", idiomatic: "Qin struck him down, killed him, tore his body apart between chariots for all to see, and wiped out his house to the last." },
  { zh: "初，商君相秦，用法嚴酷，嘗臨渭淪囚，渭水盡赤，爲相十年，人多怨之。", literal: "Earlier, as chancellor of Qin the Lord of Shang applied the law with fearful severity; once he had prisoners drowned in the Wei River until the water ran red. Ten years as chancellor, and many hated him.", idiomatic: "As Qin’s chancellor he ruled with pitiless law; once he drowned prisoners in the Wei until the river ran red. Ten years in power, and the realm hated him." },
  { zh: "趙良見商君，商君問曰：「子觀我治秦，孰與五羖大夫賢？", literal: "Zhao Liang visited the Lord of Shang, who asked, “In your view, is my governance of Qin more worthy than that of the Five-Skins Grandee?”", idiomatic: "Zhao Liang came to see him. The Lord of Shang asked, “Do you think my rule of Qin surpasses the Five-Skins Grandee’s?”" },
  { zh: "」趙良曰：「千人之諾諾，不如一士之諤諤。", literal: "” Zhao Liang said, “A thousand men murmuring yes is not worth one man’s honest no.", idiomatic: "” Zhao Liang said, “A thousand yes-men are not worth one honest no." },
  { zh: "-{僕}-請終燒正言而無誅，可乎？", literal: "-{Your servant}-begs to speak straight to the end without punishment—may I?”", idiomatic: "May I speak plainly to the end without punishment?”" },
  { zh: "」商君曰「諾。", literal: "” The Lord of Shang said, “Agreed.", idiomatic: "” The Lord of Shang said, “Agreed." },
  { zh: "」趙良曰：「五羖大夫，荊之鄙人也，穆公舉之牛口之下，而加之百姓之上，秦國莫敢望焉。", literal: "” Zhao Liang said, “The Five-Skins Grandee was a rustic man of Jing; Duke Mu raised him from beneath an ox-cart and set him above the people, and none in Qin dared look down on him.", idiomatic: "” Zhao Liang said, “The Five-Skins Grandee was a rustic of Jing. Duke Mu lifted him from under an ox-cart and set him above the people, and no one in Qin dared look down on him." },
  { zh: "相秦六七年而東伐鄭，三置晉君，一救荊禍。", literal: "As chancellor of Qin for six or seven years he attacked Zheng to the east, thrice set up the ruler of Jin, and once rescued Jing from disaster.", idiomatic: "Six or seven years as chancellor he marched east against Zheng, thrice installed Jin’s ruler, and once saved Jing from ruin." },
  { zh: "其爲相也，勞不坐乘，暑不張蓋。", literal: "As chancellor he toiled without sitting in a carriage in fatigue, nor spread a canopy in summer heat.", idiomatic: "As chancellor he would not ride when weary nor raise a parasol in summer heat." },
  { zh: "行-{於}-國中，不從車乘，不操-{干}-戈。", literal: "Traveling through the state he did not follow with chariots or carry halberd and spear.", idiomatic: "He walked the realm without an escort of chariots or arms in hand." },
  { zh: "五羖大夫死，秦國男女流涕，童子不歌謠，舂者不相杵。", literal: "When the Five-Skins Grandee died, men and women of Qin wept; children did not sing; those pounding grain did not strike the pestles together.", idiomatic: "When he died, men and women of Qin wept; children hushed their songs; mortars fell silent in the pounding-houses." },
  { zh: "今君之見也，因嬖人景監以爲主；", literal: "Your lordship’s audience came through the favorite Jing Jian as patron;", idiomatic: "You won your audience through the favorite Jing Jian;" },
  { zh: "其從政也，凌轢公族，殘傷百姓。", literal: "in governing you trampled the ducal clans and ravaged the people.", idiomatic: "in power you crushed the ducal houses and broke the people." },
  { zh: "公子虔杜門不出已八年矣。", literal: "The young lord Qian has shut his door and not gone out for eight years.", idiomatic: "Prince Qian has not left his door in eight years." },
  { zh: "君又殺祝歡而黥公孫賈。", literal: "You also killed Zhu Huan and branded Gongsun Jia.", idiomatic: "You killed Zhu Huan and branded Gongsun Jia." },
  { zh: "《詩》曰：『得人者興，失人者崩。", literal: "The Odes say: ‘He who wins men rises; he who loses men falls.", idiomatic: "The Odes say: ‘Win the people and rise; lose them and fall." },
  { zh: "』此數者，非所以得人也。", literal: "’ These several deeds are not the way to win men.”", idiomatic: "’ None of this is how you win men.”" },
  { zh: "君之出也，-{後}-車載甲，多力而駢脅者爲驂乘，持矛而操闟戟者旁車而趨。", literal: "When your lordship goes out, the rear chariot carries armor; men of great strength with ribs pressed together serve as outriders; those holding spears and wielding shield-halberds ride escort chariots and hurry along.", idiomatic: "When you go abroad, the rear chariot bears armor; brawny men with barrel chests ride as outriders; spear-bearers and halberd-men race in the flank cars." },
  { zh: "此一物不具，君固不出。", literal: "If any one of these is lacking, your lordship will not go out at all.", idiomatic: "Lack one of these and you will not stir from your gate." },
  { zh: "《書》曰：『恃德者昌，恃力者亡。", literal: "The Documents say: ‘Those who rely on virtue prosper; those who rely on force perish.", idiomatic: "The Documents say: ‘Trust in virtue and flourish; trust in force and perish." },
  { zh: "』此數者，非恃德也。", literal: "’ These several things are not relying on virtue.", idiomatic: "’ None of this is trusting in virtue." },
  { zh: "君之危若朝露，而尚貪商-{於}-之富，寵秦國之政，畜百姓之怨。", literal: "Your peril is like morning dew, yet you still covet the wealth of Shangyu, favor Qin’s government, and store up the people’s resentment.", idiomatic: "Your danger is morning dew, yet you still clutch the riches of Shangyu, court Qin’s favor, and hoard the people’s hate." },
  { zh: "秦王一旦捐賓客而不立朝，秦國之所以收君者豈其微哉！", literal: "If the king of Qin one day casts aside his guests and holds no court, would the reasons Qin has to seize your lordship be slight!", idiomatic: "If the king of Qin one day dismisses his guests and holds no court, would Qin’s grounds for taking you be small!" },
  { zh: "」商君弗從。", literal: "” The Lord of Shang did not follow his counsel.", idiomatic: "” The Lord of Shang would not listen." },
  { zh: "居五月而難作。", literal: "Five months later trouble arose.", idiomatic: "Five months on, calamity broke out." },
  { zh: "1韓申不害卒。", literal: "1 Han: Shen Buhai died.", idiomatic: "1 Han: Shen Buhai died." },
  { zh: "1宋太丘社亡。", literal: "1 Song: the Taiqiu altar society perished.", idiomatic: "1 Song: the Taiqiu altar society was lost." },
  { zh: "2鄒人孟軻見魏惠王。", literal: "2 Meng Ke of Zou had audience with King Hui of Wei.", idiomatic: "2 Meng Ke of Zou came before King Hui of Wei." },
  { zh: "王曰：「叟，不遠千-{里}-而來，亦有以利吾國乎？", literal: "The king said, “Old sir, you have come a thousand li without regard for distance—do you also have something to profit my state?”", idiomatic: "The king said, “Old master, you have traveled a thousand li—have you come with counsel to profit my state?”" },
  { zh: "」孟子曰：「君何必曰利，仁義而已矣！", literal: "” Mencius said, “Why must my lord speak of profit? Benevolence and righteousness are enough!", idiomatic: "” Mencius said, “Why speak of profit at all? Benevolence and righteousness are enough!" },
  { zh: "君曰何以利吾國，大夫曰何以利吾家，士庶人曰何以利吾身，上下交-{征}-利而國危矣。", literal: "If the lord says how to profit the state, grandees say how to profit their houses, gentlemen and commoners say how to profit themselves—high and low contend for profit and the state is in peril.", idiomatic: "If the lord asks how to profit the state, ministers ask how to profit their houses, and every man asks how to profit himself—when high and low chase profit together, the state stands in peril." },
  { zh: "未有仁而遺其親者也，未有義而-{後}-其君者也。", literal: "There has never been one benevolent who abandoned his parents, nor one righteous who put his lord last.”", idiomatic: "No benevolent man ever forsook his parents; no righteous man ever set his lord last.”" },
  { zh: "」王曰：「善。", literal: "” The king said, “Well said.", idiomatic: "” The king said, “Well said." },
  { zh: "初，孟子師子思，嘗問牧民之道何先。", literal: "At first Mencius studied under Zisi and once asked which comes first in governing the people.", idiomatic: "Earlier Mencius had studied under Zisi and once asked what should come first in tending the people." },
  { zh: "子思曰：「先利之。", literal: "Zisi said, “Put profit first.”", idiomatic: "Zisi said, “Profit comes first.”" },
  { zh: "」孟子曰：「君子所以教民，亦仁義而已矣，何必利？", literal: "” Mencius said, “The way a gentleman teaches the people is benevolence and righteousness alone—why must there be profit?”", idiomatic: "” Mencius said, “A gentleman teaches the people with benevolence and righteousness alone—why speak of profit?”" },
  { zh: "」子思曰：「仁義固所以利之也。", literal: "” Zisi said, “Benevolence and righteousness are precisely how one profits them.”", idiomatic: "” Zisi said, “Benevolence and righteousness are exactly how you profit them.”" },
  { zh: "上不仁則下不得其所，上不義則下樂爲詐也。", literal: "If those above are not benevolent, those below have no place; if those above are not righteous, those below delight in deceit.", idiomatic: "When those above lack benevolence, those below lose their footing; when those above lack righteousness, those below take joy in fraud." },
  { zh: "此爲不利大矣。", literal: "This is great unprofit.", idiomatic: "That is the greatest loss of all." },
  { zh: "故《易》曰：『利者，義之和也。", literal: "Hence the Changes say: ‘Profit is the harmony of righteousness.", idiomatic: "So the Changes say: ‘Profit is the harmony of righteousness." },
  { zh: "』又曰：『利用安身，以崇德也。", literal: "’ It also says: ‘Use profit to settle the body, thereby to honor virtue.", idiomatic: "’ And again: ‘Use profit to secure the person and thereby exalt virtue." },
  { zh: "』此皆利之大者也。", literal: "’ These are all great profits.”", idiomatic: "’ These are the greatest profits of all.”" },
  { zh: "::臣光曰：子思、孟子之言，一也。", literal: ":: Commentator Guang says: The words of Zisi and Mencius are one.", idiomatic: ":: Master Guang remarks: Zisi and Mencius speak the same truth." },
  { zh: "夫唯仁者爲知仁義之利，不仁者不知也。", literal: "Only the benevolent know the profit of benevolence and righteousness; the non-benevolent do not know.", idiomatic: "Only the benevolent grasp the profit in benevolence and righteousness; the unbenevolent cannot see it." },
  { zh: "故孟子對梁王直以仁義而不及利者，所與言之人異故也。", literal: "Hence when Mencius answered King Hui of Liang he spoke only of benevolence and righteousness and did not touch on profit—the man he addressed was different.", idiomatic: "That is why Mencius answered King Hui of Liang with benevolence and righteousness alone and never mentioned profit: the man he faced was not the same." },
  { zh: "1秦伐韓，拔宜陽。", literal: "1 Qin attacked Han and took Yiyang.", idiomatic: "1 Qin invaded Han and seized Yiyang." },
  { zh: "2〔齊王封田嬰-{於}-彭城〕<ref>〔齊王封田嬰-{於}-彭城〕-{據}-《史記·孟嘗君列傳》索隱引《紀年》補。", literal: "2 [King of Qi enfeoffed Tian Ying at Pengcheng]<ref>[King of Qi enfeoffed Tian Ying at Pengcheng]—supplied from Shiji “Biography of Lord Mengchang,” Suoyin citing the Bamboo Annals.", idiomatic: "2 [The king of Qi enfeoffed Tian Ying at Pengcheng]<ref>[King of Qi enfeoffed Tian Ying at Pengcheng]—from Shiji “Biography of Lord Mengchang,” Suoyin citing the Bamboo Annals." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "〔田嬰言-{於}-齊王曰：「五官之計，不可不日-{聽}-而數覽也。", literal: "[Tian Ying said to the king of Qi, “The accounts of the Five Offices must be heard daily and reviewed often.”", idiomatic: "[Tian Ying told the king of Qi, “The revenue tallies of the Five Offices must be heard every day and reviewed again and again.”" },
  { zh: "」王從之。", literal: "” The king followed this counsel.", idiomatic: "” The king agreed." },
  { zh: "已而厭之，悉以委田嬰。", literal: "Before long he grew weary of it and entrusted the whole to Tian Ying.", idiomatic: "Soon he wearied of the task and handed it all to Tian Ying." },
  { zh: "田嬰由是得專齊之權〕<ref>〔田嬰言-{於}-齊王曰〕句此段本-{繫}--{於}-周顯王四十八年，今移入此年，-{並}-改「靖郭君」爲「田嬰」。", literal: "Tian Ying thereby came to monopolize Qi’s power]<ref>The passage beginning [Tian Ying said to the king of Qi] was originally attached to year forty-eight of King Xian of Zhou; it is moved to this year, and “Lord Jingguo” is changed to “Tian Ying.”", idiomatic: "From this Tian Ying held Qi’s power alone]<ref>The passage [Tian Ying said to the king of Qi] was tied to year forty-eight of King Xian of Zhou; moved here, with “Lord Jingguo” changed to “Tian Ying.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1〔田嬰相齊〕。", literal: "1 [Tian Ying became chancellor of Qi].", idiomatic: "1 [Tian Ying became chancellor of Qi]." },
  { zh: "齊王、魏王會-{于}-徐州以相王。", literal: "The kings of Qi and Wei met at Xuzhou to recognize each other as kings.", idiomatic: "The kings of Qi and Wei met at Xuzhou and acknowledged each other as kings." },
  { zh: "〔楚王聞之，怒田嬰〕<ref>〔田嬰相齊〕……〔楚王聞之怒田嬰〕-{據}-《史記·孟嘗君列傳》補。", literal: "[When the king of Chu heard of it, he was angry at Tian Ying]<ref>[Tian Ying became chancellor of Qi] … [when the king of Chu heard of it he was angry at Tian Ying]—supplied from Shiji “Biography of Lord Mengchang.”", idiomatic: "[The king of Chu heard and raged at Tian Ying]<ref>[Tian Ying became chancellor of Qi] … [the king of Chu heard and raged at Tian Ying]—from Shiji “Biography of Lord Mengchang.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2韓昭侯作髙門，屈宜臼曰：「君必不出此門。", literal: "2 King Zhao of Han built a tall gate. Qu Yijiu said, “My lord will surely not pass through this gate.", idiomatic: "2 King Zhao of Han raised a lofty gate. Qu Yijiu said, “You will never walk through this gate." },
  { zh: "何也？", literal: "Why?”", idiomatic: "Why?”" },
  { zh: "不時。", literal: "It is not timely.”", idiomatic: "The time is wrong.”" },
  { zh: "吾所謂時者，非時日也。", literal: "What I call timeliness is not the hour or the day.", idiomatic: "By timeliness I do not mean the calendar." },
  { zh: "夫人固有利、不利時。", literal: "Men by nature have times of profit and times of loss.", idiomatic: "Every man has seasons when fortune favors him and seasons when it does not." },
  { zh: "往者君嘗利矣，不作髙門。", literal: "In the past my lord was once in profit and did not build a tall gate.", idiomatic: "Once you were favored by fortune and built no lofty gate." },
  { zh: "前年秦拔宜陽，今年旱，君不以此時恤民之急而顧益奢，此所謂時詘舉贏者也。", literal: "The year before last Qin took Yiyang; this year there is drought. My lord does not at this time relieve the people’s distress but instead grows more extravagant—this is what is called lifting a load when momentum fails and hoarding when times are flush.", idiomatic: "Two years ago Qin seized Yiyang; this year the land is dry. You do not ease the people’s distress now but add to your splendor—this is doing the costly thing when times are lean and the profitable thing when times are fat." },
  { zh: "故曰不時。", literal: "Hence I say it is not timely.”", idiomatic: "That is why I say the time is wrong.”" },
  { zh: "3越王無疆伐齊。", literal: "3 King Wujiang of Yue attacked Qi.", idiomatic: "3 King Wujiang of Yue invaded Qi." },
  { zh: "齊王使人説之以伐齊不如伐楚之利，越王遂伐楚。", literal: "The king of Qi sent a man to persuade him that attacking Chu was more profitable than attacking Qi; the king of Yue thereupon attacked Chu.", idiomatic: "The king of Qi sent a persuader to argue that raiding Chu would profit him more than raiding Qi; the king of Yue turned south against Chu." },
  { zh: "楚人大敗之，乘勝盡取呉故地，東至-{于}-浙江。", literal: "The men of Chu routed him utterly and, pressing the victory, took all the old lands of Wu as far east as the Zhe River.", idiomatic: "Chu shattered his army, then swept up every former Wu territory east to the Zhe River." },
  { zh: "越以此散，諸公族爭立，或爲王，或爲君，濱-{於}-海上，朝服-{於}-楚。", literal: "Yue thereby dissolved; the ducal clans contended for the throne, some making themselves kings and some lords, clinging to the seacoast and paying court to Chu in Chu’s robes.", idiomatic: "Yue broke apart; rival princes of the royal house fought for power, some styling themselves kings and some lords, holding the coast and doing homage to Chu in Chu dress." },
  { zh: "1楚王伐齊，〔敗齊師〕，圍徐州，〔使人逐田嬰。", literal: "1 The king of Chu attacked Qi, [defeated the Qi army], and besieged Xuzhou, [and sent men to drive out Tian Ying.", idiomatic: "1 The king of Chu struck Qi, [broke the Qi army], and besieged Xuzhou, [and sent men to hunt down Tian Ying." },
  { zh: "田嬰使張-{丑}-説楚王，楚王乃止〕<ref>〔敗齊師〕……〔使人逐田嬰田嬰使張-{丑}-説楚王楚王乃止〕-{據}-《史記·孟嘗君列傳》補。", literal: "Tian Ying sent Zhang Chou to persuade the king of Chu, and the king of Chu then stopped]<ref>[Defeated the Qi army] … [sent men to drive out Tian Ying; Tian Ying sent Zhang Chou to persuade the king of Chu and the king of Chu stopped]—supplied from Shiji “Biography of Lord Mengchang.”", idiomatic: "Tian Ying sent Zhang Chou to win over the king of Chu, and the king of Chu desisted]<ref>[Defeated the Qi army] … [sent men to hunt Tian Ying; Tian Ying sent Zhang Chou to persuade the king of Chu and he stopped]—from Shiji “Biography of Lord Mengchang.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2韓髙門成，昭侯薨，子宣惠王立。", literal: "2 Han’s tall gate was finished; King Zhao died; his son King Xuanhui succeeded.", idiomatic: "2 Han’s lofty gate was completed; King Zhao died; his son King Xuanhui succeeded." },
  { zh: "初，洛陽人蘇秦説秦王以兼天下之-{術}-，秦王不用其言。", literal: "At first Su Qin of Luoyang urged the king of Qin with the art of uniting All-under-Heaven; the king of Qin did not employ his words.", idiomatic: "Earlier Su Qin of Luoyang had urged the king of Qin with stratagems to master the realm; the king of Qin would not hear him." },
  { zh: "蘇秦乃去，説燕文公曰：「燕之所以不犯寇被甲兵者，以趙之爲蔽其南也。", literal: "Su Qin then left and urged Duke Wen of Yan, “The reason Yan is not harried by raiders and does not don armor is that Zhao shields its south.", idiomatic: "Su Qin departed and told Duke Wen of Yan, “Yan is not overrun by raiders nor forced to arm its men because Zhao stands as your shield to the south." },
  { zh: "且秦之攻燕也，戰-{於}-千-{里}-之外；", literal: "Moreover when Qin attacks Yan, it fights a thousand li away;", idiomatic: "When Qin strikes Yan, the battle is a thousand li off;" },
  { zh: "趙之攻燕也，戰-{於}-百-{里}-之内。", literal: "when Zhao attacks Yan, it fights within a hundred li.", idiomatic: "when Zhao strikes Yan, the battle is within a hundred li." },
  { zh: "夫不憂百-{里}-之患而重千-{里}-之外，計無過-{於}-此者。", literal: "To fret not over a hundred-li threat yet weigh a thousand-li distance—no plan goes beyond this in folly.", idiomatic: "To ignore a danger a hundred li away while dreading one a thousand li off—no strategy is more foolish." },
  { zh: "-{願}-大王與趙從親，天下爲一，則燕國必無患矣。", literal: "-{I pray}-that the great king ally with Zhao in horizontal union; if All-under-Heaven is one, Yan will surely be without trouble.”", idiomatic: "Let the great king join Zhao in a vertical alliance; unite the realm, and Yan will know no peril.”" },
  { zh: "」文公從之，資蘇秦車馬，以説趙肅侯曰：「當今之時，山東之建國莫強-{於}-趙，秦之所害亦莫如趙。", literal: "” Duke Wen followed this counsel, supplied Su Qin with chariots and horses, and sent him to urge Marquis Su of Zhao: “In the present age, among the states founded east of the mountains none is stronger than Zhao, and none does Qin hate more than Zhao.", idiomatic: "” The duke agreed, equipped Su Qin with chariots and horses, and sent him to persuade Marquis Su of Zhao: “Of all the states east of the mountains, none is stronger than Zhao today, and none does Qin fear to wound more." },
  { zh: "然而秦不敢舉兵伐趙者，畏韓、魏之議其-{後}-也。", literal: "Yet Qin dares not raise troops to attack Zhao because it fears Han and Wei plotting behind it.", idiomatic: "Yet Qin dares not march on Zhao because it dreads Han and Wei striking from the rear." },
  { zh: "秦之攻韓、魏也，無有名山大川之限，稍蠶食之，傅國都而止。", literal: "When Qin attacks Han and Wei there are no famous mountains or great rivers to bar it; bit by bit it nibbles away until it presses the royal capital.", idiomatic: "Against Han and Wei Qin meets no mountain barrier or river wall; it gnaws them away until its armies stand at their capitals." },
  { zh: "韓、魏不能支秦，必入臣-{於}-秦。", literal: "Han and Wei cannot withstand Qin and are sure to submit as vassals to Qin.", idiomatic: "Han and Wei cannot hold Qin off and will bow as Qin’s vassals." },
  { zh: "秦無韓、魏之規則禍中-{於}-趙矣。", literal: "With no Han or Wei to scheme against, calamity will strike Zhao in the center.", idiomatic: "Once Han and Wei no longer stand in its way, Qin’s blow will fall square on Zhao." },
  { zh: "臣以天下〔之〕地圖案之<ref>臣以天下〔之〕地圖案之-{據}-《史記·蘇秦列傳》補「之」字。", literal: "Your servant lays the map of All-under-Heaven’s [lands] before you<ref>Your servant lays the map of All-under-Heaven’s [lands] before you—the character “之” supplied from Shiji “Biography of Su Qin.”", idiomatic: "I have spread the map of All-under-Heaven’s [domains] before you<ref>…All-under-Heaven’s [lands]…—the character “之” from Shiji “Biography of Su Qin.”" },
  { zh: "</ref>，諸侯之地五倍-{於}-秦，料度諸侯之卒十倍-{於}-秦。", literal: "</ref>: the feudal lords’ lands are five times Qin’s; reckoned, their soldiers are ten times Qin’s.", idiomatic: "</ref>: the lords’ territories are five times Qin’s; count their soldiers and they are tenfold." },
  { zh: "六國爲一，-{並}-力西鄕而攻秦，秦必破矣。", literal: "If the six states are one and join strength to march west against Qin, Qin is sure to be broken.", idiomatic: "Unite the six states, turn every spear west, and Qin must fall." },
  { zh: "夫衡人者皆欲割諸侯之地以與秦，秦成則其身富榮，國被秦患而不與其憂，是以衡人日夜務以秦權恐愒諸侯，以求割地。", literal: "The horizontal men all wish to carve off the feudal lords’ lands and give them to Qin. When Qin succeeds they themselves grow rich and honored while their states suffer Qin’s harm and share not its grief. Hence the horizontal men day and night work to frighten the feudal lords with Qin’s power and seek cessions of land.", idiomatic: "The advocates of appeasement all want to slice off the lords’ lands for Qin. When Qin prospers they grow rich and grand while their own states bear Qin’s scourge and they feel none of its pain. That is why these men work day and night to terrify the lords with Qin’s might and wring territory from them." },
  { zh: "故-{願}-大王熟計之也！", literal: "Therefore -{I pray}-the great king weigh this carefully!", idiomatic: "I beg the great king to reckon this through!" },
  { zh: "竊爲大王計，莫如一韓、魏、齊、楚、燕、趙爲從親以畔秦，令天下之將相會-{於}-洹水上，通質結盟，約曰：『秦攻一國，五國各出鋭師，或橈秦，或救之。", literal: "In private counsel for the great king, nothing surpasses having Han, Wei, Qi, Chu, Yan, and Zhao unite in vertical alliance to turn from Qin, gathering the realm’s generals and chancellors at the Huan River to exchange hostages and covenant, with the pact: ‘If Qin attacks one state, the other five each send crack troops either to harass Qin or to rescue the victim.", idiomatic: "My private counsel: let Han, Wei, Qi, Chu, Yan, and Zhao stand together in vertical alliance against Qin. Summon every general and minister to the Huan River, exchange hostages, and swear: ‘If Qin strikes one of us, the other five will each send elite troops to harry Qin or relieve the besieged." },
  { zh: "有不如約者，五國共伐之！", literal: "Whoever fails the covenant, the five states attack together!’", idiomatic: "Whoever breaks the pact, the five will strike him together!’" },
  { zh: "』諸侯從親以擯秦，秦甲必不敢出-{於}-函-{谷}-以害山東矣。", literal: "’ If the feudal lords unite vertically to shut out Qin, Qin’s armor will surely not dare emerge from Hangu Pass to harm the lands east of the mountains.”", idiomatic: "’ Bind the lords in vertical union to bar Qin, and Qin’s armies will not dare pass Hangu to harm the east.”" },
  { zh: "」肅侯大悅，厚待蘇秦，尊寵賜賚之，以約-{於}-諸侯。", literal: "” Marquis Su was greatly pleased, treated Su Qin generously, honored and rewarded him, and used him to covenant with the feudal lords.", idiomatic: "” Marquis Su was delighted, treated Su Qin with rich favor, heaped titles and gifts on him, and sent him to seal pacts among the lords." },
  { zh: "會秦使犀首伐魏，大敗其師四萬-{餘}-人，禽將龍賈，取雕陰，且欲東兵。", literal: "Just then Qin sent Xishou to attack Wei and routed more than forty thousand of its troops, captured the general Long Jia, took Diaoyin, and was about to march east.", idiomatic: "At that moment Qin sent Xishou against Wei, shattered more than forty thousand men, took General Long Jia prisoner, seized Diaoyin, and prepared to drive east." },
  { zh: "蘇秦恐秦兵至趙而敗從約，念莫可使用-{於}-秦者，乃激怒張儀，入之-{於}-秦。", literal: "Su Qin feared that if Qin’s army reached Zhao the vertical covenant would fail; thinking of no one who could be used against Qin, he provoked Zhang Yi and sent him into Qin.", idiomatic: "Su Qin feared that Qin’s march on Zhao would shatter the vertical pact. Seeing no one else who could sway Qin, he baited Zhang Yi and sent him into Qin’s service." },
  { zh: "張儀者，魏人，與蘇秦倶事鬼-{谷}-先生，學縱橫之-{術}-，蘇秦自以爲不及也。", literal: "Zhang Yi was a man of Wei who, with Su Qin, studied under Master Guigu the arts of vertical and horizontal alliance; Su Qin thought himself no match for him.", idiomatic: "Zhang Yi was from Wei. He and Su Qin had both studied the arts of alliance and counter-alliance under Master Guigu; Su Qin knew himself the lesser man." },
  { zh: "儀-{游}-諸侯無所遇，困-{於}-楚，蘇秦故召而辱之。", literal: "Yi wandered among the feudal lords without meeting favor and was stranded in Chu; Su Qin deliberately summoned him and humiliated him.", idiomatic: "Yi had wandered the courts without patron and was stranded in Chu; Su Qin deliberately summoned him only to shame him." },
  { zh: "儀怒，念諸侯獨秦能苦趙，遂入秦。", literal: "Yi was enraged; reflecting that among the feudal lords only Qin could afflict Zhao, he entered Qin.", idiomatic: "Burning with anger, he reflected that only Qin among the powers could break Zhao—and went to Qin." },
  { zh: "蘇秦陰遣其-{舍}-人齎金幣資儀，儀得見秦王。", literal: "Su Qin secretly sent his retainer with gold to supply Yi; Yi gained audience with the king of Qin.", idiomatic: "Su Qin secretly sent a retainer with gold to fund him; Zhang Yi won audience with the king of Qin." },
  { zh: "秦王説之，以爲客卿。", literal: "The king of Qin was pleased with him and made him guest minister.", idiomatic: "The king of Qin took to him and made him a guest minister." },
  { zh: "-{舍}-人辭去，曰：「蘇君憂秦伐趙敗從約，以爲非君莫能得秦柄，故激怒君，使臣陰奉給君資，盡蘇君之計謀也。", literal: "-{The retainer}-took leave and said, “Lord Su feared that if Qin attacked Zhao the vertical covenant would fail; thinking no one but you could win Qin’s power, he provoked you and had me secretly supply you with funds—this is entirely Lord Su’s stratagem.”", idiomatic: "The retainer took his leave and said, “Lord Su feared Qin’s attack on Zhao would ruin the vertical pact. Believing no one but you could seize Qin’s ear, he provoked you and had me fund you in secret—all of this was Lord Su’s design.”" },
  { zh: "」張儀曰：「嗟乎！", literal: "” Zhang Yi said, “Alas!", idiomatic: "” Zhang Yi said, “Ah!" },
  { zh: "此在吾-{術}-中而不悟，吾不及蘇君明矣。", literal: "This lay within my art and I did not grasp it—I am clearly not the equal of Lord Su.”", idiomatic: "This was within my own craft and I never saw it—I am far less clear-sighted than Lord Su.”" },
  { zh: "爲吾謝蘇君，蘇君之時，儀何敢言！", literal: "Bear my thanks to Lord Su: while Lord Su’s time lasts, how dare Yi speak!”", idiomatic: "Give Lord Su my thanks: while Lord Su holds the field, what dare Yi say!”" },
  { zh: "-{於}-是蘇秦説韓宣惠王曰：「韓地方九百-{餘}--{里}-，帶甲數十萬，天下之強弓、勁弩、利劍皆從韓出。", literal: "-{Thereupon}-Su Qin urged King Xuanhui of Han: “Han’s territory is more than nine hundred li; it fields several hundred thousand armored men; the realm’s strongest bows, stiffest crossbows, and sharpest swords all come from Han.", idiomatic: "Then Su Qin urged King Xuanhui of Han: “Han spans more than nine hundred li and fields several hundred thousand armored men. The strongest bows, the stiffest crossbows, and the keenest blades in the realm all come from Han." },
  { zh: "韓卒超足而射，百-{發}-不暇止。", literal: "Han’s soldiers shoot with feet braced and loose a hundred bolts without pause.", idiomatic: "Han’s soldiers plant their feet and shoot a hundred bolts without drawing breath." },
  { zh: "以韓卒之勇，被堅甲，跖勁弩，帶利劍，一人當百，不足言也。", literal: "With Han soldiers’ courage, clad in hard armor, bracing powerful crossbows, bearing sharp swords—one man worth a hundred—this goes without saying.", idiomatic: "Arm them in hard mail, set them behind powerful crossbows, gird them with sharp swords—one man matches a hundred. That scarcely needs saying." },
  { zh: "大王事秦，秦必求宜陽、成皋。", literal: "If the great king serves Qin, Qin is sure to demand Yiyang and Chenggao.", idiomatic: "Serve Qin, great king, and Qin will demand Yiyang and Chenggao." },
  { zh: "今茲效之，明年又-{復}-求割地。", literal: "Grant them this year and next year it will demand land again.", idiomatic: "Yield them now and next year Qin will demand more." },
  { zh: "與則無地以給之，不與則棄前功，受-{後}-禍。", literal: "If you give, you have no land left to satisfy it; if you refuse, you forfeit your prior gains and suffer later calamity.", idiomatic: "Give, and you will have no land left to satisfy Qin; refuse, and you throw away what you have already paid and invite worse ruin." },
  { zh: "且大王之地有盡而秦之求無已，以有盡之地逆無已之求，此所謂市怨結禍者也。", literal: "Moreover the great king’s lands have bounds while Qin’s demands have no end; to meet endless demands with bounded lands—this is what is called buying resentment and knitting disaster.", idiomatic: "Your lands are finite but Qin’s appetite is not. To feed an endless hunger from a finite store—that is buying hatred and weaving your own doom." },
  { zh: "不戰而地已削矣！", literal: "Without fighting your lands are already shaved away!", idiomatic: "Without a battle your territory is already gone!" },
  { zh: "鄙諺曰：『-{寧}-爲鷄口，無爲牛-{後}-。", literal: "A rustic saying runs: ‘-{Better}-be a chicken’s beak than an ox’s rump.", idiomatic: "A country saying runs: ‘Better be the chicken’s beak than the ox’s hindquarters." },
  { zh: "』夫以大王之賢，挾強韓之兵，而有牛-{後}-之名，臣竊爲大王羞之。", literal: "’ With the great king’s worth, wielding strong Han’s armies, yet bearing the name of an ox’s rump—your servant is privately ashamed for the great king.”", idiomatic: "’ With your wisdom and strong Han’s armies at your back, yet to wear the name of an ox’s tail—your servant is ashamed for you.”" },
  { zh: "」韓王從其言。", literal: "” The king of Han followed his words.", idiomatic: "” The king of Han took his counsel." },
  { zh: "蘇秦説魏王曰：「大王之地方千-{里}-，地名雖小，然而田-{舍}-、廬廡之數，曾無所芻牧。", literal: "Su Qin urged the king of Wei: “Your majesty’s territory is a thousand li; the name is small, yet the count of farmsteads and outbuildings is such that nowhere is left for grazing fodder.", idiomatic: "Su Qin urged the king of Wei: “Your realm spans a thousand li. The name is modest, yet farmsteads and storehouses crowd the land so thickly that no pasture is left unfenced." },
  { zh: "人民之衆，車馬之多，日夜行不絶，輷輷殷殷，若有三軍之衆。", literal: "The people are multitudinous, chariots and horses numerous; they travel day and night without cease, rumbling and thundering as if there were the host of three armies.”", idiomatic: "Your people are countless, your chariots and horses beyond numbering; they move day and night without pause, wheels thundering as though three armies marched the roads.”" },
  { zh: "臣竊量大王之國不下楚。", literal: "Your servant privately estimates that Your Majesty's state is not inferior to Chu.", idiomatic: "I reckon Your Majesty's realm is no lesser than Chu's." },
  { zh: "今竊聞大王之卒，武士二十萬，蒼頭二十萬，奮撃二十萬，廝徒十萬；", literal: "Now I have privately heard that Your Majesty's troops number two hundred thousand warriors, two hundred thousand convict soldiers, two hundred thousand assault troops, and one hundred thousand servants and laborers;", idiomatic: "I hear you field two hundred thousand warriors, two hundred thousand penal troops, two hundred thousand shock troops, and one hundred thousand auxiliaries;" },
  { zh: "車六百乘，騎五千匹，乃-{聽}--{於}-群臣之説，而欲臣事秦。", literal: "six hundred chariots and five thousand horses—yet you hearken to your ministers' counsel and wish to serve Qin as a vassal.", idiomatic: "six hundred chariot teams and five thousand horses—yet you heed your ministers and would bow to Qin as its servant." },
  { zh: "〔-{願}-大王熟察之〕<ref>〔-{願}-大王熟察之〕章校「乙十一行本『秦』下有『-{願}-大王熟察之』六字；", literal: "[May Your Majesty consider this carefully]<ref>[May Your Majesty consider this carefully] Zhang's collation: “In the Yi eleven-line edition, after ‘Qin’ stand the six characters ‘May Your Majesty consider this carefully’;", idiomatic: "[May Your Majesty weigh this carefully]<ref>[May Your Majesty weigh this carefully]—Zhang's collation: “In the Yi eleven-line edition, after ‘Qin’ stand the six characters ‘May Your Majesty weigh this carefully’;" },
  { zh: "孔本同；", literal: "the Kong edition agrees;", idiomatic: "Kong edition agrees;" },
  { zh: "張校同；", literal: "Zhang's collation agrees;", idiomatic: "Zhang's collation agrees;" },
  { zh: "退齋校同」，《史記·蘇秦列傳》有此六字，-{據}-補。", literal: "Tui Zhai's collation agrees.” Shiji “Biography of Su Qin” has these six characters; supplied per that text.", idiomatic: "Tui Zhai's collation agrees.” Shiji “Biography of Su Qin” has these six characters—supplied from there." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "故敝邑趙王使臣效愚計，奉明約，以大王之詔詔之。", literal: "Therefore our lord the King of Zhao sent me to offer this humble plan, to present a clear covenant, and to announce it with Your Majesty's own decree.", idiomatic: "So the King of Zhao sent me with this humble scheme, a clear covenant, and Your Majesty's mandate to proclaim it abroad." },
  { zh: "」魏王-{聽}-之。", literal: "” The King of Wei heeded him.", idiomatic: "” The King of Wei took his counsel." },
  { zh: "蘇秦説齊王曰：「齊四塞之國，地方二千-{餘}--{里}-，帶甲數十萬，粟如丘山。", literal: "Su Qin said to the King of Qi, “Qi is a state sealed on four sides, with territory of more than two thousand li, several hundred thousand armored men, and grain piled like hills.", idiomatic: "Su Qin told the King of Qi, “Qi is walled in on every side—more than two thousand li of land, hundreds of thousands under arms, grain heaped like hills." },
  { zh: "三軍之良，五家之兵，進如鋒矢，戰如雷霆，解如風雨。", literal: "The elite of the three armies and the troops of five-household groups advance like arrowheads, fight like thunder, and disengage like wind and rain.", idiomatic: "Your best troops and household levies strike like arrowheads, crash like thunder, and withdraw like a storm breaking." },
  { zh: "卽有軍役，未嘗倍泰山，絶淸河，渉渤海也。", literal: "Even when there is military service, they have never had to double Mount Tai, cross the Qing River, or ford the Bohai.", idiomatic: "Even in wartime your men need not march past Mount Tai, ford the Qing, or cross the Bohai." },
  { zh: "臨菑之中七萬戸，臣竊度之，不下戸三男子，不待-{發}--{於}-遠縣，而臨菑之卒固已二十一萬矣。", literal: "Within Linzi there are seventy thousand households; your servant privately reckons no household has fewer than three adult men—without waiting to mobilize distant counties, Linzi alone already fields two hundred ten thousand soldiers.", idiomatic: "Linzi holds seventy thousand households; I count at least three fighting men per door—without calling up distant counties, Linzi alone can put two hundred ten thousand men in the field." },
  { zh: "臨菑甚富而實，其民無不-{鬥}-鷄、走狗、六博、闒鞠。", literal: "Linzi is very rich and full of substance; its people all cockfight, race dogs, play liubo, and kick cuju.", idiomatic: "Linzi is flush and crowded; every man cockfights, races dogs, plays liubo, or kicks the cuju ball." },
  { zh: "臨菑之塗，車轂撃，人肩摩，連衽成帷，揮汗成雨。", literal: "On Linzi's streets chariot hubs strike one another, shoulders rub, linked sleeves form curtains, and flicked sweat falls like rain.", idiomatic: "On Linzi's streets axle hubs clash, shoulders grind, sleeves knit into walls of cloth, and sweat flies like rain." },
  { zh: "夫韓、魏之所以重畏秦者，爲與秦接境壤也。", literal: "The reason Han and Wei fear Qin so deeply is that they share a border with Qin.", idiomatic: "Han and Wei dread Qin because they share its border." },
  { zh: "兵出而相當，不十日而戰勝存亡之機決矣。", literal: "When troops go forth and meet, within ten days the issue of victory, defeat, survival, or ruin is decided.", idiomatic: "Armies meet at the frontier and within ten days survival or ruin is settled." },
  { zh: "韓、魏戰而勝秦，則兵半折，四境不守；", literal: "If Han and Wei fight and defeat Qin, their armies are halved and their borders cannot be held;", idiomatic: "If Han and Wei beat Qin, half their forces are broken and their borders lie open;" },
  { zh: "戰而不勝，則國已危亡隨其-{後}-。", literal: "if they fight and do not win, the state is already lost and ruin follows close behind.", idiomatic: "if they lose, the state is gone and ruin follows at their heels." },
  { zh: "是故韓、魏之所以重與秦戰而輕爲之臣也。", literal: "Therefore Han and Wei dread fighting Qin yet lightly submit as its vassals.", idiomatic: "That is why Han and Wei dread war with Qin yet readily bow as its servants." },
  { zh: "今秦之攻齊則不然。", literal: "Now Qin's attack on Qi is not so.", idiomatic: "Qi's case is different." },
  { zh: "倍韓、魏之地，過衞陽晉之道，經乎亢父之險，車不得方軌，騎不得比行。", literal: "It must double Han and Wei territory, pass the road through Wei's Yangjin, thread the peril of Kangfu—chariots cannot run two abreast, horsemen cannot ride in ranks.", idiomatic: "Qin must march across Han and Wei, pass Yangjin in Wei, and squeeze through Kangfu's defile—chariots cannot run abreast, cavalry cannot keep formation." },
  { zh: "百人守險，千人不敢過也。", literal: "A hundred men holding the pass and a thousand dare not cross.", idiomatic: "A hundred men on the heights and a thousand will not pass." },
  { zh: "秦雖欲深入則狼顧，恐韓、魏之議其-{後}-也。", literal: "Though Qin wishes to press deep, it looks back like a wolf, fearing Han and Wei will strike its rear.", idiomatic: "Even if Qin drives deep, it glances back like a wolf, fearing Han and Wei at its rear." },
  { zh: "是故恫疑、虚喝、驕矜而不敢進，則秦之不能害齊亦明矣。", literal: "Therefore it blusters, shouts empty threats, swaggers yet dares not advance—so it is clear Qin cannot harm Qi.", idiomatic: "So it blusters and threatens yet dares not advance—plainly Qin cannot hurt Qi." },
  { zh: "夫不深料秦之無奈齊何，而欲西-{面}-而事之，是群臣之計過也。", literal: "Not to reckon deeply that Qin can do nothing against Qi, yet wish to turn west and serve it—this is your ministers' error in counsel.", idiomatic: "Not to see that Qin is helpless against Qi, yet turn west and serve it—that is your ministers' blunder." },
  { zh: "今無臣事秦之名而有強國之寶，臣是故-{願}-大王少留意計之。", literal: "Now you may avoid the name of serving Qin yet keep the treasure of a strong state; your servant therefore begs Your Majesty to give the plan a little thought.", idiomatic: "You need not bear the name of Qin's vassal yet may keep a great power's strength—please weigh this, Majesty." },
  { zh: "」齊王許之。", literal: "” The King of Qi agreed.", idiomatic: "” The King of Qi agreed." },
  { zh: "乃西南説楚威王曰：「楚，天下之強國也，地方六千-{餘}--{里}-，帶甲百萬，車千乘，騎萬匹，粟支十年，此霸王之資也。", literal: "He then went southwest and said to King Wei of Chu, “Chu is the strongest state under Heaven, with territory of more than six thousand li, a million armored men, a thousand chariots, ten thousand horses, and grain to last ten years—this is the capital of a hegemon-king.", idiomatic: "He went southwest to King Wei of Chu and said, “Chu is the strongest realm under Heaven—six thousand li and more, a million under arms, a thousand chariots, ten thousand horses, grain for ten years: the stuff of empire." },
  { zh: "秦之所害莫如楚，楚強則秦弱，秦強則楚弱，其勢不兩立。", literal: "Of all Qin harms, none equals Chu; when Chu is strong Qin is weak, when Qin is strong Chu is weak—their momentum cannot stand together.", idiomatic: "Qin fears nothing like Chu; when Chu grows strong Qin weakens, when Qin grows strong Chu weakens—the two cannot stand together." },
  { zh: "故爲大王計，莫如從親以孤秦。", literal: "Therefore for Your Majesty's counsel, nothing surpasses joining the vertical alliance to isolate Qin.", idiomatic: "For Your Majesty, nothing beats the vertical alliance to isolate Qin." },
  { zh: "臣請令山東之國奉四時之獻，以承大王之明詔。", literal: "Your servant asks to have the states east of the mountains present seasonal tribute to receive Your Majesty's enlightened commands.", idiomatic: "I will have the eastern states bring seasonal tribute and await your command." },
  { zh: "委社稷，奉宗廟，練士厲兵，在大王之所用之。", literal: "They will entrust their altars of soil and grain, serve your ancestral temples, drill troops and sharpen weapons—all at Your Majesty's disposal.", idiomatic: "They will entrust state and temple, drill men and hone arms—whatever you command." },
  { zh: "故從親則諸侯割地以事楚，衡合則楚割地以事秦。", literal: "Thus with the vertical alliance the feudal lords cede land to serve Chu; with the horizontal alliance Chu cedes land to serve Qin.", idiomatic: "Under the vertical league the lords cede land to serve Chu; under the horizontal league Chu cedes land to serve Qin." },
  { zh: "此兩策者相去遠矣，大王何居焉？", literal: "These two policies stand far apart—where does Your Majesty stand?", idiomatic: "The two paths could not be further apart—where does Your Majesty stand?" },
  { zh: "」楚王亦許之。", literal: "” The King of Chu also agreed.", idiomatic: "” The King of Chu agreed as well." },
  { zh: "-{於}-是蘇秦爲從約長，-{並}-相六國，北報趙，車騎輜重擬-{於}-王者。", literal: "-{Thereupon}-Su Qin became chief of the vertical covenant, simultaneous premier of the six states; returning north to report to Zhao, his chariots, horsemen, and baggage train rivaled a king's.", idiomatic: "Su Qin became head of the vertical league and simultaneous premier of six states; reporting north to Zhao, his train of chariots, horses, and baggage matched a king's." },
  { zh: "3齊王知成侯賣田忌，乃召而-{復}-之。", literal: "3 The King of Qi learned that Marquis Cheng had betrayed Tian Ji and summoned Tian Ji back to office.", idiomatic: "3 The King of Qi learned Marquis Cheng had sold out Tian Ji and recalled him to office." },
  { zh: "4燕文公薨，子易王立。", literal: "4 Duke Wen of Yan died; his son King Yi succeeded.", idiomatic: "4 Duke Wen of Yan died; his son King Yi succeeded." },
  { zh: "5衞成侯薨，子平侯立。", literal: "5 Marquis Cheng of Wei died; his son Marquis Ping succeeded.", idiomatic: "5 Marquis Cheng of Wei died; his son Marquis Ping succeeded." },
  { zh: "1秦惠王使犀首欺齊、魏，與共伐趙，以敗從約。", literal: "1 King Hui of Qin sent Xishou to deceive Qi and Wei into joining him in attacking Zhao, thereby breaking the vertical covenant.", idiomatic: "1 King Hui of Qin sent Xishou to trick Qi and Wei into joining an attack on Zhao and shatter the vertical league." },
  { zh: "趙肅侯讓蘇秦，蘇秦恐，請使燕，必報齊。", literal: "Marquis Su of Zhao reproached Su Qin; Su Qin was afraid and asked to be sent to Yan, vowing he would surely repay Qi.", idiomatic: "Marquis Su of Zhao blamed Su Qin; in fear Su Qin asked to go to Yan, swearing he would settle accounts with Qi." },
  { zh: "蘇秦去趙而從約皆解。", literal: "Su Qin left Zhao and the vertical covenant dissolved entirely.", idiomatic: "Su Qin quit Zhao and the vertical league fell apart." },
  { zh: "趙人決河水以灌齊、魏之師，齊、魏之師乃去。", literal: "The men of Zhao breached the Yellow River to flood the armies of Qi and Wei, and the armies of Qi and Wei thereupon withdrew.", idiomatic: "Zhao cut the Yellow River banks and drowned Qi and Wei's hosts, and they withdrew." },
  { zh: "2魏以陰晉爲和-{於}-秦，實華陰。", literal: "2 Wei ceded Yinjun to Qin for peace; in fact this was Huayin.", idiomatic: "2 Wei ceded Yinjun to Qin for peace—the place was Huayin." },
  { zh: "3齊王伐燕，取十城，已而-{復}-歸之。", literal: "3 The King of Qi attacked Yan, took ten cities, and afterward returned them.", idiomatic: "3 The King of Qi invaded Yan, seized ten cities, then gave them back." },
  { zh: "1秦伐魏，圍焦、-{曲}-沃。", literal: "1 Qin attacked Wei and besieged Jiao and Quwo.", idiomatic: "1 Qin attacked Wei and besieged Jiao and Quwo." },
  { zh: "魏入少梁、河西地-{於}-秦。", literal: "Wei surrendered Shaoliang and the lands west of the river to Qin.", idiomatic: "Wei surrendered Shaoliang and the Hexi lands to Qin." },
  { zh: "1秦伐魏，渡河，取汾陰、皮氏，拔焦。", literal: "1 Qin attacked Wei, crossed the river, took Fenyin and Pishi, and captured Jiao.", idiomatic: "1 Qin struck Wei, crossed the river, took Fenyin and Pishi, and seized Jiao." },
  { zh: "2楚威王薨，子懷王槐立。", literal: "2 King Wei of Chu died; his son King Huai, Huai, succeeded.", idiomatic: "2 King Wei of Chu died; his son King Huai Huai succeeded." },
  { zh: "〔魏聞楚喪，伐楚，取陘山〕<ref>〔魏聞楚喪伐楚取陘山〕-{據}-《史記·趙世家》補。", literal: "[When Wei heard of Chu's mourning, it attacked Chu and took Yin Mountain]<ref>[When Wei heard of Chu's mourning, attacked Chu, and took Yin Mountain]—supplied from Shiji “House of Zhao.”", idiomatic: "[Hearing of Chu's mourning, Wei attacked Chu and took Yin Mountain]<ref>[When Wei heard of Chu's mourning, attacked Chu, and took Yin Mountain]—from Shiji “House of Zhao.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "3宋公剔成之弟偃襲攻剔成。", literal: "3 The younger brother of Duke Ticheng of Song, Yan, launched a surprise attack on Ticheng.", idiomatic: "3 Duke Ticheng of Song's brother Yan struck and overthrew him." },
  { zh: "剔成奔齊，偃自立爲君。", literal: "Ticheng fled to Qi; Yan installed himself as ruler.", idiomatic: "Ticheng fled to Qi; Yan made himself ruler." },
  { zh: "1秦公子華、張儀帥師圍魏蒲陽，取之。", literal: "1 The Qin lords Hua and Zhang Yi led troops to besiege Puyang in Wei and took it.", idiomatic: "1 Prince Hua of Qin and Zhang Yi besieged Wei's Puyang and took it." },
  { zh: "張儀言-{於}-秦王，請以蒲陽-{復}-與魏，而使公子繇質-{於}-魏。", literal: "Zhang Yi said to the King of Qin, asking that Puyang be returned to Wei and that the young lord Yao be sent as hostage to Wei.", idiomatic: "Zhang Yi asked the King of Qin to return Puyang to Wei and send Prince Yao to Wei as hostage." },
  { zh: "儀因説魏王曰：「秦之遇魏甚厚，魏不可以無禮-{於}-秦。", literal: "Yi then said to the King of Wei, “Qin has treated Wei with great generosity; Wei cannot be without courtesy toward Qin.", idiomatic: "He then told the King of Wei, “Qin has shown Wei great favor; Wei must not slight Qin." },
  { zh: "」魏因盡入上郡十五縣以謝焉。", literal: "” Wei thereupon surrendered all fifteen counties of Shang commandery by way of thanks.", idiomatic: "” Wei thereupon ceded all fifteen counties of Shang commandery in gratitude." },
  { zh: "張儀歸而相秦。", literal: "Zhang Yi returned and became chancellor of Qin.", idiomatic: "Zhang Yi returned and became Qin's chancellor." },
  { zh: "1秦縣義渠，以其君爲臣。", literal: "1 Qin made Yiqu a commandery and took its lord as vassal.", idiomatic: "1 Qin turned Yiqu into a commandery and reduced its lord to vassal." },
  { zh: "2秦歸焦、-{曲}-沃-{於}-魏。", literal: "2 Qin returned Jiao and Quwo to Wei.", idiomatic: "2 Qin returned Jiao and Quwo to Wei." },
  { zh: "1趙肅侯薨，子武靈王〔雍〕立<ref>子武靈王〔雍〕立-{據}-《史記·趙世家》索隱補。", literal: "1 Marquis Su of Zhao died; his son King Wuling [Yong] succeeded<ref>King Wuling [Yong] succeeded—supplied from Shiji “House of Zhao,” Suoyin.", idiomatic: "1 Marquis Su of Zhao died; his son King Wuling [Yong] succeeded<ref>King Wuling [Yong] succeeded—from Shiji “House of Zhao,” Suoyin." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "置博聞師三人，左、右司過三人，先問先君貴臣肥義，加其秩。", literal: "He appointed three Broad-Hearing Masters and three Left and Right Fault-Finders; he first consulted his father's honored minister Fei Yi and raised his rank.", idiomatic: "He named three Masters of Broad Hearing and three Left and Right Fault-Finders; he consulted his father's old minister Fei Yi first and raised his rank." },
  { zh: "1夏，四月，戊午，秦初稱王。", literal: "1 In summer, the fourth month, on wuwu day, Qin first styled itself king.", idiomatic: "1 In summer, fourth month, on wuwu day, Qin first took the title of king." },
  { zh: "2衞平侯薨，子嗣君立。", literal: "2 Marquis Ping of Wei died; his son Lord Si succeeded.", idiomatic: "2 Marquis Ping of Wei died; his son Lord Si succeeded." },
  { zh: "衞有胥靡亡之魏，因爲魏王之-{后}-治病。", literal: "In Wei (衛) there was a convict laborer named Xu Mi who fled to Wei (魏) and there treated the queen's illness.", idiomatic: "A convict named Xu Mi fled the state of Wei (衛) for Wei (魏) and treated the queen's illness there." },
  { zh: "嗣君聞之，〔使人〕請以五十金買之<ref>〔使人〕請以五十金買之章校「十二行本『之』下有『使人』二字；", literal: "Lord Si heard of it and [sent a man] to ask to buy him for fifty gold<ref>[sent a man] to ask to buy him for fifty gold—Zhang's collation: “In the twelve-line edition, after ‘him’ stand the two characters ‘sent a man’;", idiomatic: "Lord Si heard and [sent a man] offering fifty gold to buy him<ref>[sent a man] offering fifty gold—Zhang's collation: “In the twelve-line edition, after ‘him’ stand ‘sent a man’;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "the Kong edition agrees;", idiomatic: "Kong edition agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai's collation agrees.", idiomatic: "Tui Zhai's collation agrees." },
  { zh: "」，《戰國策·行策》第十四章有此二字，-{據}-補。", literal: "” Strategies of the Warring States, “Conduct Strategies,” chapter fourteen has these two characters; supplied per that text.", idiomatic: "” Strategies of the Warring States, “Conduct Strategies,” chapter 14 has these two characters—supplied from there." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "五反，魏不與，乃以左氏易之。", literal: "Five times he sent envoys; Wei would not yield him, so he exchanged the district of Zuoshi for him.", idiomatic: "Five embassies failed; Wei refused, so he traded the district of Zuoshi for the man." },
  { zh: "左右諫曰：「夫以一都買一胥靡，可乎？", literal: "Those at his side remonstrated, saying, “To buy one convict laborer with an entire district—is that permissible?”", idiomatic: "His counselors said, “Trade a whole district for one convict—is that wise?”" },
  { zh: "」嗣君曰：「非子所知也。", literal: "” Lord Si said, “This is not what you understand.", idiomatic: "” Lord Si said, “You do not understand." },
  { zh: "夫治無小，亂無大。", literal: "In governing there is no trifle; in disorder there is no great matter.", idiomatic: "In good order nothing is too small; in chaos nothing is too great." },
  { zh: "法不立，誅不必，雖有十左氏，無益也。", literal: "If the law is not established and punishments are not certain, even ten Zuoshi districts would be of no use.", idiomatic: "If law does not stand and punishment is uncertain, ten Zuoshis would not help." },
  { zh: "法立，誅必，失十左氏，無害也。", literal: "If the law is established and punishment is certain, to lose ten Zuoshi districts does no harm.", idiomatic: "If law stands and punishment is sure, losing ten Zuoshis does no harm." },
  { zh: "」魏王聞之曰：「人主之欲，不-{聽}-之不祥。", literal: "” When the King of Wei heard, he said, “A ruler's desire—failure to heed it is ill-omened.", idiomatic: "” The King of Wei heard and said, “When a lord desires something, to refuse him is ill-omened." },
  { zh: "」因載而往，徒獻之。", literal: "” He had Xu Mi carried there and presented him as a gift without payment.", idiomatic: "” He had Xu Mi carried to Wei and gave him away outright." },
  { zh: "1秦張儀帥師伐魏，取陝。", literal: "1 Zhang Yi of Qin led troops against Wei and took Shan.", idiomatic: "1 Zhang Yi of Qin invaded Wei and took Shan." },
  { zh: "2蘇秦通-{於}-燕文公之夫人，易王知之。", literal: "2 Su Qin had relations with the consort of Duke Wen of Yan; King Yi learned of it.", idiomatic: "2 Su Qin lay with Duke Wen of Yan's queen; King Yi found out." },
  { zh: "蘇秦恐，乃説易王曰：「臣居燕不能使燕重，而在齊則燕重。", literal: "Su Qin was afraid and therefore said to King Yi, “Your servant dwelling in Yan cannot make Yan weighty, but if I am in Qi then Yan grows weighty.", idiomatic: "Su Qin in fear told King Yi, “While I stay in Yan I cannot raise Yan's standing—but in Qi I can make Yan weighty." },
  { zh: "」易王許之。", literal: "” King Yi agreed.", idiomatic: "” King Yi agreed." },
  { zh: "乃偽得罪-{於}-燕而奔齊，齊宣王以爲客卿。", literal: "He then pretended to have offended Yan and fled to Qi; King Xuan of Qi made him guest minister.", idiomatic: "He feigned offense against Yan and fled to Qi; King Xuan of Qi made him a guest minister." },
  { zh: "蘇秦説齊王髙宮室，大苑囿，以明得意，欲以敝齊而爲燕。", literal: "Su Qin urged the King of Qi to raise palaces high and enlarge parks and preserves, to display his triumph, intending to exhaust Qi for Yan's sake.", idiomatic: "Su Qin urged the King of Qi to build towering palaces and vast parks, flaunting his triumph, intending to wear Qi down for Yan." },
  { zh: "1秦張儀及齊、楚之相會嚙桑。", literal: "1 Zhang Yi of Qin and the chancellors of Qi and Chu met at Nie Sang.", idiomatic: "1 Zhang Yi of Qin met the chancellors of Qi and Chu at Nie Sang." },
  { zh: "2韓、燕皆稱王，趙武靈王獨不肯，曰：「無其實，敢處其名乎？", literal: "2 Han and Yan both styled themselves kings; King Wuling of Zhao alone refused, saying, “Without the substance, how dare one hold the name?”", idiomatic: "2 Han and Yan both took royal titles; King Wuling of Zhao alone refused: “Without the substance, who dares wear the name?”" },
  { zh: "」令國人謂己曰君。", literal: "” He ordered the people of his state to call him lord.", idiomatic: "” He ordered his people to call him lord." },
  { zh: "3〔魯景公薨，子平公旅立〕<ref>〔魯景公薨子平公旅立〕舊文本-{繫}--{於}-愼靚王四年，-{據}-近人考-{証}-移入此年。", literal: "3 [Duke Jing of Lu died; his son Duke Ping, Lü, succeeded]<ref>[Duke Jing of Lu died; Duke Ping Lü succeeded]—old text was tied to the fourth year of King Shenjing; moved to this year per modern scholars' research.", idiomatic: "3 [Duke Jing of Lu died; his son Duke Ping Lü succeeded]<ref>[Duke Jing of Lu died; Duke Ping Lü succeeded]—old text placed this in year four of King Shenjing; moved here per modern chronology." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1秦張儀自嚙桑還而免相，相魏。", literal: "1 Zhang Yi of Qin, returning from Nie Sang, was removed as chancellor and became chancellor of Wei.", idiomatic: "1 Zhang Yi returned from Nie Sang, left Qin's chancellorship, and became Wei's chancellor." },
  { zh: "欲令魏先事秦而諸侯效之，魏王不-{聽}-。", literal: "He wished to make Wei serve Qin first so the feudal lords would follow; the King of Wei would not heed him.", idiomatic: "He meant Wei to serve Qin first so other lords would follow; the King of Wei refused." },
  { zh: "秦王伐魏，取-{曲}-沃、平周。", literal: "The King of Qin attacked Wei and took Quwo and Pingzhou.", idiomatic: "The King of Qin struck Wei and took Quwo and Pingzhou." },
  { zh: "-{復}-陰厚張儀益甚。", literal: "-{Again}-in secret he treated Zhang Yi all the more generously.", idiomatic: "In secret he treated Zhang Yi more generously than ever." },
  { zh: "2〔夏，四月〕<ref>〔夏四月〕-{據}-《史記·孟嘗君列傳》索隱引《紀年》補。", literal: "2 [Summer, fourth month]<ref>[Summer, fourth month]—supplied from Shiji “Biography of Lord Mengchang,” Suoyin citing the Bamboo Annals.", idiomatic: "2 [Summer, fourth month]<ref>[Summer, fourth month]—from Shiji “Biography of Lord Mengchang,” Suoyin citing the Bamboo Annals." },
  { zh: "</ref>，齊王封田嬰-{於}-薛，號曰靖郭君。", literal: "</ref>, the King of Qi enfeoffed Tian Ying at Xue and styled him Lord Jingguo.", idiomatic: "</ref> the King of Qi enfeoffed Tian Ying at Xue as Lord Jingguo." },
  { zh: "靖郭君言-{於}-齊王曰：「五官之計不可不日-{聽}-而數覽也」王從之，已而厭之，悉以委靖郭君。", literal: "Lord Jingguo said to the King of Qi, “The accounts of the five offices cannot go unreviewed day by day and perused often.” The king followed this counsel; later he grew weary of it and entrusted everything to Lord Jingguo.", idiomatic: "Lord Jingguo told the King of Qi, “The five bureaus' accounts must be heard daily and read often.” The king agreed; soon he tired of it and handed everything to Lord Jingguo." },
  { zh: "由是得專政齊之權。", literal: "From this he came to monopolize government authority in Qi.", idiomatic: "From this he monopolized power in Qi." },
  { zh: "靖郭君欲城薛，客謂靖郭君曰：「君不聞海大魚乎？", literal: "Lord Jing of Guo wished to fortify Xue; a guest said to him, “Have you not heard of the great fish of the sea?", idiomatic: "Lord Jing of Guo wished to wall Xue; a guest said to him, “Have you never heard of the great fish of the sea?" },
  { zh: "網不能止，鉤不能牽，蕩而失水，則螻蟻-{制}-焉。", literal: "Nets cannot hold it, hooks cannot draw it; cast adrift and losing the water, then ants and mole-crickets may master it.", idiomatic: "No net can hold it, no hook can haul it—adrift and stripped of water, ants and mole-crickets master it." },
  { zh: "今夫齊，亦君之水也。", literal: "Now Qi, too, is your water.", idiomatic: "Qi is your water now." },
  { zh: "君長有齊，奚以薛爲！", literal: "If you long hold Qi, what need have you of Xue!", idiomatic: "Hold Qi for life—what need of Xue!" },
  { zh: "苟爲失齊，雖隆薛之城到-{於}-天，庸足恃乎？", literal: "If you should lose Qi, though you piled Xue’s walls to heaven, how could you rely on them?", idiomatic: "Lose Qi, and though Xue’s walls reached the sky, what could you trust?" },
  { zh: "」乃不果城。", literal: "” He then did not fortify it after all.", idiomatic: "” He abandoned the fortification." },
  { zh: "靖郭君有子四十〔-{餘}-〕人<ref>靖郭君有子四十〔-{餘}-〕人章校「十二行本『十』下有『-{餘}-』字；", literal: "Lord Jing of Guo had forty [-{餘}-] sons<ref>Lord Jing of Guo had forty [-{餘}-] sons—Zhang’s collation: the twelve-line edition has the character [-{餘}-] under “ten”;", idiomatic: "Lord Jing of Guo had forty [-{餘}-] sons<ref>Lord Jing of Guo had forty [-{餘}-] sons—Zhang’s collation: the twelve-line edition has [-{餘}-] after “ten”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong’s edition agrees.", idiomatic: "Kong’s edition agrees." },
  { zh: "」，《史記·孟嘗君列傳》有此字，-{據}-補。", literal: "” Shiji “Biography of Lord Mengchang” has this character; supplied by [-{據}-] collation.", idiomatic: "” Shiji “Biography of Lord Mengchang” has this character; supplied by collation." },
  { zh: "</ref>，其賤妾之子曰文。", literal: "</ref>, and a son by a low concubine was called Wen.", idiomatic: "</ref>, and a son by a humble concubine was named Wen." },
  { zh: "文通儻饒智略，説靖郭君以散財養士。", literal: "Wen was unrestrained and richly endowed with stratagems; he persuaded Lord Jing of Guo to scatter wealth and nourish retainers.", idiomatic: "Wen was bold and brimmed with stratagems; he urged Lord Jing of Guo to spend his fortune keeping men." },
  { zh: "靖郭君使文主家待賓客，賓客爭譽其美，皆請靖郭君以文爲嗣。", literal: "Lord Jing of Guo had Wen manage the household and receive guests; guests vied to praise his excellence, and all asked Lord Jing of Guo to make Wen his heir.", idiomatic: "Lord Jing of Guo put Wen in charge of the house and guests; guests praised him to the skies, and all begged that Wen be made heir." },
  { zh: "靖郭君卒，文嗣爲薛公，號曰孟嘗君。", literal: "When Lord Jing of Guo died, Wen succeeded as Lord of Xue and was styled Lord Mengchang.", idiomatic: "When Lord Jing of Guo died, Wen succeeded as Lord of Xue and took the title Lord Mengchang." },
  { zh: "孟嘗君招致諸侯-{游}-士及有罪亡人，皆-{捨}-業厚遇之，存救其親戚。", literal: "Lord Mengchang gathered wandering scholars of the feudal lords and men guilty and in flight; all he treated with generous favor, abandoning their former trades, and he preserved and rescued their kin.", idiomatic: "Lord Mengchang gathered wandering scholars and fugitives from every state, lavished favors on them, and let them abandon their old callings while he saved their kin." },
  { zh: "食客常數千人，各自以爲孟嘗君親己。", literal: "His retainers often numbered several thousand; each thought Lord Mengchang treated him as kin.", idiomatic: "His retainers often numbered in the thousands; each believed Lord Mengchang favored him alone." },
  { zh: "由是孟嘗君之名重天下。", literal: "From this Lord Mengchang’s fame weighed heavy throughout the realm.", idiomatic: "Thus Lord Mengchang’s name weighed on the world." },
  { zh: "::臣光曰：君子之養士，以爲民也。", literal: ":: Your servant Guang says: When a gentleman nourishes retainers, it is for the sake of the people.", idiomatic: "Sima Guang remarks: A gentleman keeps retainers for the people’s sake." },
  { zh: "《易》曰：「聖人養賢，以及萬民。", literal: "The Changes says: “The sage nourishes the worthy to reach the myriad people.", idiomatic: "The Changes says: “The sage nourishes the worthy to reach the myriad people." },
  { zh: "」夫賢者，其德足以敦化正俗，其-{才}-足以頓綱振紀，其明足以燭微慮遠，其強足以結仁固義。", literal: "” The worthy man’s virtue suffices to deepen transformation and set customs right; his [-{才}-] suffices to brace the net and rouse the statutes; his clarity suffices to illumine the subtle and ponder the far; his strength suffices to bind benevolence and firm righteousness.", idiomatic: "” The worthy man’s virtue can deepen custom and set the age right; his talent can brace the laws and rouse order; his clarity can pierce the subtle and see far; his strength can bind benevolence and firm loyalty." },
  { zh: "大則利天下，小則利一國。", literal: "On a great scale he benefits all under heaven; on a small scale he benefits one state.", idiomatic: "At greatest he profits the realm; at least he profits one state." },
  { zh: "是以君子-{豐}-祿以富之，隆爵以尊之。", literal: "Therefore the gentleman [-{豐}-] enriches him with ample stipend and honors him with exalted rank.", idiomatic: "Therefore the gentleman heaps stipend and wealth on him and raises him in rank and honor." },
  { zh: "養一人而及萬人者，養賢之道也。", literal: "To nourish one man and thereby reach ten thousand men—this is the Way of nourishing the worthy.", idiomatic: "To keep one man and thereby reach ten thousand—that is how the worthy are kept." },
  { zh: "今孟嘗君之養士也，不恤智愚，不擇臧否，盜其君之祿，以立私黨，張虚譽，上以侮其君，下以蠹其民，是-{奸}-人之雄也，烏足尚哉！", literal: "Now in Lord Mengchang’s nourishing of retainers he does not care whether they are wise or foolish, does not choose good or bad; he steals his lord’s stipends to build a private faction, spreads empty fame, above insults his ruler, below harms the people—he is chief among [-{奸}-] men; how is he fit to be esteemed!", idiomatic: "Lord Mengchang keeps men without regard to wit or folly, good or ill; he steals his ruler’s pay to build a private faction, trades in hollow fame, insults his prince above and devours the people below—chief among villains; what is there to admire!" },
  { zh: "《書》曰：「受爲天下逋逃主、萃淵藪。", literal: "The Documents says: “Zhou was lord of fugitives for all under heaven, a gathering pool and deep lair.", idiomatic: "The Documents says: “Zhou was lord of fugitives for all under heaven, a gathering pool and deep lair." },
  { zh: "」此之謂也。", literal: "” This is what is meant.", idiomatic: "” This is what is meant." },
  { zh: "1王崩，子愼靚王定立。", literal: "1 The king died; his son King Shenjing, Ding, was established.", idiomatic: "1 The Zhou king died; his son King Shenjing Ding succeeded." },
  { zh: "2燕易王薨，子噲立。", literal: "2 King Yi of Yan died; his son Kuai succeeded.", idiomatic: "2 King Yi of Yan died; his son Kuai succeeded." },
  { zh: "3孟嘗君聘-{於}-楚，楚王遺之象床。", literal: "3 Lord Mengchang went on a mission to Chu; the king of Chu sent him off with a couch of ivory.", idiomatic: "3 Lord Mengchang went on a mission to Chu; the king of Chu gave him an ivory couch as a parting gift." },
  { zh: "登徒直送之，不欲行，謂孟嘗君門人公孫戌曰：「象床之直千金，苟傷之毫-{髮}-，則賣妻子不足償也。", literal: "Dengtu Zhi was to escort it but did not wish to go; he said to Gongsun Xu, a retainer of Lord Mengchang, “The ivory couch is worth a thousand in gold; if a single [-{髮}-] of it is harmed, selling wife and children would not suffice to pay.", idiomatic: "Dengtu Zhi was to escort it but refused; he told Gongsun Xu, a retainer of Lord Mengchang, “The ivory couch is worth a thousand in gold; scratch a single hair of it and selling wife and children would not cover the debt." },
  { zh: "足下能使-{僕}-無行者，有先人之寶劍，-{願}-獻之。", literal: "If you, sir, can make [-{僕}-] not go, I have my forefathers’ treasured sword and [-{願}-] offer it.", idiomatic: "If you can spare me the journey, I have my forefathers’ treasured sword and would give it to you." },
  { zh: "」公孫戌許諾，入見孟嘗君曰：「小國所以皆致相印-{於}-君者，以君能振達貧窮，存亡繼絶，故莫不悅君之義，慕君之廉也。", literal: "” Gongsun Xu promised, entered, and saw Lord Mengchang, saying, “The reason small states all bestow their seals of chancellor on you is that you can raise up the poor, preserve states on the verge of ruin and continue severed lineages; therefore none fail to delight in your righteousness and admire your integrity.", idiomatic: "” Gongsun Xu agreed, went in, and told Lord Mengchang, “Small states lend you their chancellor’s seal because you lift the poor, save dying kingdoms, and continue broken lines—everyone delights in your righteousness and admires your integrity." },
  { zh: "今始至楚而受象床，則未至之國將何以待君哉！", literal: "Now, having just reached Chu, you accept an ivory couch—how will states you have not yet reached receive you!", idiomatic: "Accept an ivory couch the moment you reach Chu, and what will the states you have not yet visited think of you!" },
  { zh: "」孟嘗君曰：「善。", literal: "” Lord Mengchang said, “Well said.", idiomatic: "” Lord Mengchang said, “Good." },
  { zh: "」遂不受。", literal: "” He then did not accept it.", idiomatic: "” He refused the gift." },
  { zh: "公孫戌趨去，未至中閨，孟嘗君召而反之，曰：「子何足之髙，-{志}-之揚也？", literal: "Gongsun Xu hurried away; before reaching the inner court Lord Mengchang summoned him back and said, “Why are your feet so high, your [-{志}-] so lifted?", idiomatic: "Gongsun Xu hurried off; before he reached the inner court Lord Mengchang called him back: “Why the high step, the lifted brow?" },
  { zh: "」公孫戌以實對。", literal: "” Gongsun Xu answered with the truth.", idiomatic: "” Gongsun Xu told him the whole truth." },
  { zh: "孟嘗君乃書門版曰：「有能揚文之名，止文之過，私得寶-{於}-外者，疾入諫！", literal: "Lord Mengchang then wrote on the gate board: “Whoever can spread Wen’s fame, stop Wen’s faults, or has privately received treasure from without—hurry in with remonstrance!", idiomatic: "Lord Mengchang then posted on the gate: “Whoever can spread Wen’s good name, check Wen’s faults, or has taken private gifts from abroad—come in at once and speak!" },
  { zh: "::臣光曰：孟嘗君可謂能用諫矣。", literal: ":: Your servant Guang says: Lord Mengchang may be called one who could use remonstrance.", idiomatic: "Sima Guang remarks: Lord Mengchang may be said to have known how to heed counsel." },
  { zh: "苟其言之善也，雖懷詐諼之心，猶將用之，況盡忠無私以事其上乎！", literal: "If the words are good, though one harbors a heart of deceitful flattery, he would still employ them—how much more one who serves his superior with full loyalty and no selfishness!", idiomatic: "If the words are sound, he would use them even from a flatterer with a deceitful heart—how much more from a man who serves his lord with full loyalty and no private aim!" },
  { zh: "《詩》-{云}-：「采葑采菲，無以下體。", literal: "The Odes [-{云}-]: “Gather turnip tops, gather radish leaves; do not reject them for the lower part.", idiomatic: "The Odes say: “Gather turnip tops, gather radish leaves; do not reject them for the lower part." },
  { zh: "」孟嘗君有焉。", literal: "” Lord Mengchang had this.", idiomatic: "” Lord Mengchang had this." },
  { zh: "4韓宣惠王欲兩用公仲、公叔爲政，問-{於}-繆留。", literal: "4 King Xuanhui of Han wished to employ both Gongsun Zhong and Gongsun Shu in government and questioned Miu Liu.", idiomatic: "4 King Xuanhui of Han wished to use both Gongsun Zhong and Gongsun Shu in power and asked Miu Liu." },
  { zh: "對曰：「不可。", literal: "He replied, “It cannot be done.", idiomatic: "He replied, “No." },
  { zh: "晉用六卿而國分，齊簡公用陳成子及闞止而見殺，魏用犀首、張儀而西河之外亡。", literal: "Jin employed the Six Clans and the state was divided; Duke Jian of Qi employed Chen Chengzi and Kan Zhi and was killed; Wei employed Xishou and Zhang Yi and lost the lands beyond the Western River.", idiomatic: "Jin used the Six Clans and the state split; Duke Jian of Qi used Chen Chengzi and Kan Zhi and was murdered; Wei used Gongsun Yan and Zhang Yi and lost everything west of the Yellow River." },
  { zh: "今君兩用之，其多力者内樹黨，其寡力者藉外權。", literal: "Now if you employ both, the stronger will build factions within, the weaker will borrow power from without.", idiomatic: "Use both now and the stronger will build factions at home while the weaker leans on foreign power." },
  { zh: "群臣有内樹黨以驕主，有外爲交以削地，君之國危矣！", literal: "When ministers build factions within to make the lord arrogant, or make alliances without to carve away territory, your state is in peril!", idiomatic: "When ministers build factions at home to browbeat their lord and make alliances abroad to carve away land, your state is in peril!" },
  { zh: "=校刊記=<divclass=\"references-small\"><references/></div>", literal: "=Collation Notes=<motion.divclass=\"references-small\"><references/></motion.div>", idiomatic: "=Collation Notes=<motion.divclass=\"references-small\"><references/></motion.div>" },
  { zh: "周", literal: "Zhou", idiomatic: "Zhou" }
];
